#!/usr/bin/env ts-node
// FreeLang v8 ML — .fl8 파일 실행기 (fl8 CLI)

import * as fs from "fs";
import * as path from "path";
import { Lexer } from "./lexer/lexer";
import { Parser } from "./parser/parser";
import { Interpreter } from "./runtime/interpreter";

function main() {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    console.log("사용법: fl8 <파일.fl8>");
    console.log("       fl8 -e '<코드>'");
    process.exit(1);
  }

  let source: string;
  let filename: string;

  if (args[0] === "-e") {
    source = args[1] ?? "";
    filename = "<stdin>";
  } else {
    filename = args[0];
    if (!fs.existsSync(filename)) {
      console.error(`파일 없음: ${filename}`);
      process.exit(1);
    }
    source = fs.readFileSync(filename, "utf-8");
  }

  // Lex
  const lexer = new Lexer(source);
  const { tokens, errors: lexErrors } = lexer.tokenize();

  if (lexErrors.length > 0) {
    for (const e of lexErrors) {
      console.error(`[Lex 오류] ${filename}:${e.line}:${e.col}: ${e.message}`);
    }
    process.exit(1);
  }

  // Parse
  const parser = new Parser(tokens);
  const { program, errors: parseErrors } = parser.parse();

  if (parseErrors.length > 0) {
    for (const e of parseErrors) {
      console.error(`[파서 오류] ${filename}:${e.line}:${e.col}: ${e.message}`);
    }
    process.exit(1);
  }

  // Interpret
  const interp = new Interpreter();
  try {
    interp.run(program);
  } catch (e: any) {
    console.error(`[런타임 오류] ${e.message}`);
    process.exit(1);
  }
}

main();

