// FreeLang v8 ML — 패키지 매니저 (Phase 6)
// fl8.json 기반 패키지 시스템

import * as fs from 'fs';
import * as path from 'path';
import * as https from 'https';
import * as http from 'http';

// ============================================================
// fl8.json 스키마
// ============================================================

export interface FL8Manifest {
  name: string;
  version: string;
  description?: string;
  main?: string;           // 진입점 (.fl8 파일)
  dependencies?: Record<string, string>;  // { "pkg": "^1.0.0" }
  devDependencies?: Record<string, string>;
  scripts?: Record<string, string>;
  author?: string;
  license?: string;
  repository?: string;
  keywords?: string[];
  // ML 특화 메타데이터
  ml?: {
    framework?: string;   // "freelang-v8"
    tasks?: string[];     // ["classification", "generation"]
    datasets?: string[];
  };
}

export interface LockEntry {
  version: string;
  resolved: string;  // 패키지 URL 또는 GOGS 경로
  integrity: string; // SHA256 해시
  deps?: Record<string, string>;
}

export interface FL8Lock {
  version: number;
  packages: Record<string, LockEntry>;
}

// ============================================================
// PackageManager 클래스
// ============================================================

export class PackageManager {
  private projectDir: string;
  private manifestPath: string;
  private lockPath: string;
  private pkgDir: string;

  constructor(projectDir: string = process.cwd()) {
    this.projectDir = projectDir;
    this.manifestPath = path.join(projectDir, 'fl8.json');
    this.lockPath = path.join(projectDir, 'fl8.lock');
    this.pkgDir = path.join(projectDir, 'fl8_packages');
  }

  // ─── manifest ──────────────────────────────────────────────

  readManifest(): FL8Manifest | null {
    if (!fs.existsSync(this.manifestPath)) return null;
    return JSON.parse(fs.readFileSync(this.manifestPath, 'utf-8'));
  }

  writeManifest(manifest: FL8Manifest): void {
    fs.writeFileSync(this.manifestPath, JSON.stringify(manifest, null, 2) + '\n');
  }

  readLock(): FL8Lock {
    if (!fs.existsSync(this.lockPath)) {
      return { version: 1, packages: {} };
    }
    return JSON.parse(fs.readFileSync(this.lockPath, 'utf-8'));
  }

  writeLock(lock: FL8Lock): void {
    fs.writeFileSync(this.lockPath, JSON.stringify(lock, null, 2) + '\n');
  }

  // ─── init ──────────────────────────────────────────────────

  init(options: Partial<FL8Manifest> = {}): FL8Manifest {
    if (fs.existsSync(this.manifestPath)) {
      throw new Error(`fl8.json이 이미 존재합니다: ${this.manifestPath}`);
    }

    const manifest: FL8Manifest = {
      name: options.name ?? path.basename(this.projectDir),
      version: options.version ?? '0.1.0',
      description: options.description ?? '',
      main: options.main ?? 'main.fl8',
      dependencies: {},
      devDependencies: {},
      scripts: {
        run: 'fl8 main.fl8',
        test: 'fl8 tests/run.fl8',
      },
      author: options.author ?? '',
      license: options.license ?? 'MIT',
      ml: {
        framework: 'freelang-v8',
        tasks: [],
      },
    };

    this.writeManifest(manifest);
    return manifest;
  }

  // ─── install ───────────────────────────────────────────────

  install(pkgName?: string, version?: string): InstallResult {
    const manifest = this.readManifest();
    if (!manifest) {
      throw new Error('fl8.json 없음. fl8 init 먼저 실행하세요.');
    }

    if (!fs.existsSync(this.pkgDir)) {
      fs.mkdirSync(this.pkgDir, { recursive: true });
    }

    if (!pkgName) {
      // 모든 의존성 설치
      return this.installAll(manifest);
    }

    // 특정 패키지 설치
    const resolvedVersion = version ?? 'latest';
    const result = this.installPackage(pkgName, resolvedVersion, manifest);

    // manifest 업데이트
    manifest.dependencies = manifest.dependencies ?? {};
    manifest.dependencies[pkgName] = `^${result.version}`;
    this.writeManifest(manifest);

    // lock 업데이트
    const lock = this.readLock();
    lock.packages[pkgName] = {
      version: result.version,
      resolved: result.resolved,
      integrity: result.integrity,
    };
    this.writeLock(lock);

    return result;
  }

  private installAll(manifest: FL8Manifest): InstallResult {
    const deps = { ...manifest.dependencies, ...manifest.devDependencies };
    const results: InstallResult[] = [];

    for (const [name, versionRange] of Object.entries(deps)) {
      const version = versionRange.replace(/^[\^~]/, '');
      try {
        const result = this.installPackage(name, version, manifest);
        results.push(result);
      } catch (e: any) {
        console.warn(`  경고: ${name} 설치 실패 — ${e.message}`);
      }
    }

    return {
      name: '__all__',
      version: 'N/A',
      resolved: this.pkgDir,
      integrity: '',
      count: results.length,
    };
  }

  private installPackage(name: string, version: string, _manifest: FL8Manifest): InstallResult {
    const pkgPath = path.join(this.pkgDir, name);

    // 로컬 패키지 (경로 시작 ./ or /)
    if (name.startsWith('./') || name.startsWith('/')) {
      return this.installLocal(name, pkgPath);
    }

    // GOGS 패키지 (gogs:repo/name 형식)
    if (name.startsWith('gogs:')) {
      return this.installFromGogs(name.slice(5), version, pkgPath);
    }

    // 빌트인 패키지 (freelang-v8 코어 패키지)
    if (BUILTIN_PACKAGES.has(name)) {
      return this.installBuiltin(name, pkgPath);
    }

    // 기본: 심볼릭 로컬 설치 (개발 단계)
    return this.installStub(name, version, pkgPath);
  }

  private installLocal(srcPath: string, destPath: string): InstallResult {
    const absPath = path.resolve(this.projectDir, srcPath);
    if (!fs.existsSync(absPath)) {
      throw new Error(`로컬 패키지 없음: ${absPath}`);
    }

    if (!fs.existsSync(destPath)) {
      fs.mkdirSync(destPath, { recursive: true });
    }

    // fl8.json 읽기
    const manifestPath = path.join(absPath, 'fl8.json');
    if (!fs.existsSync(manifestPath)) {
      throw new Error(`${absPath}에 fl8.json 없음`);
    }

    const manifest: FL8Manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf-8'));

    // .fl8 파일 복사
    copyDir(absPath, destPath, ['.fl8', '.json']);

    return {
      name: manifest.name,
      version: manifest.version,
      resolved: absPath,
      integrity: simpleHash(absPath + manifest.version),
    };
  }

  private installFromGogs(repoPath: string, _version: string, destPath: string): InstallResult {
    // GOGS API를 통한 패키지 다운로드 (간소화 버전)
    const gogsBase = 'https://gogs.dclub.kr';
    const resolved = `${gogsBase}/${repoPath}`;

    if (!fs.existsSync(destPath)) {
      fs.mkdirSync(destPath, { recursive: true });
    }

    // stub: 실제 구현에서는 git clone 또는 archive 다운로드
    const stubManifest: FL8Manifest = {
      name: repoPath.split('/').pop() ?? repoPath,
      version: '0.0.1',
      description: `GOGS 패키지: ${repoPath}`,
    };
    fs.writeFileSync(
      path.join(destPath, 'fl8.json'),
      JSON.stringify(stubManifest, null, 2)
    );

    return {
      name: stubManifest.name,
      version: stubManifest.version,
      resolved,
      integrity: simpleHash(resolved),
    };
  }

  private installBuiltin(name: string, destPath: string): InstallResult {
    if (!fs.existsSync(destPath)) {
      fs.mkdirSync(destPath, { recursive: true });
    }

    const pkg = BUILTIN_PACKAGES.get(name)!;

    // 빌트인 패키지 fl8 코드 작성
    fs.writeFileSync(path.join(destPath, 'index.fl8'), pkg.source);
    fs.writeFileSync(
      path.join(destPath, 'fl8.json'),
      JSON.stringify({
        name,
        version: pkg.version,
        description: pkg.description,
        main: 'index.fl8',
      }, null, 2)
    );

    return {
      name,
      version: pkg.version,
      resolved: `builtin:${name}`,
      integrity: simpleHash(pkg.source),
    };
  }

  private installStub(name: string, version: string, destPath: string): InstallResult {
    // 개발 단계: stub 패키지 생성
    if (!fs.existsSync(destPath)) {
      fs.mkdirSync(destPath, { recursive: true });
    }

    const stubSource = `// ${name} v${version} — stub\nprint("패키지 로드: ${name}")`;
    fs.writeFileSync(path.join(destPath, 'index.fl8'), stubSource);
    fs.writeFileSync(
      path.join(destPath, 'fl8.json'),
      JSON.stringify({ name, version, main: 'index.fl8' }, null, 2)
    );

    return {
      name,
      version,
      resolved: `stub:${name}@${version}`,
      integrity: simpleHash(name + version),
    };
  }

  // ─── publish ───────────────────────────────────────────────

  publish(options: PublishOptions = {}): PublishResult {
    const manifest = this.readManifest();
    if (!manifest) {
      throw new Error('fl8.json 없음');
    }

    // 필수 필드 검증
    if (!manifest.name || !manifest.version) {
      throw new Error('fl8.json에 name, version 필수');
    }

    // 패키지 파일 수집
    const files = this.collectFiles(options.include);

    // GOGS 배포 (실제 구현에서는 git push)
    const publishTo = options.registry ?? 'gogs.dclub.kr/kim';

    return {
      name: manifest.name,
      version: manifest.version,
      registry: publishTo,
      files: files.length,
      success: true,
      url: `https://${publishTo}/${manifest.name}`,
    };
  }

  private collectFiles(include?: string[]): string[] {
    const patterns = include ?? ['**/*.fl8', 'fl8.json', 'README.md'];
    const files: string[] = [];

    function walk(dir: string) {
      for (const entry of fs.readdirSync(dir)) {
        const full = path.join(dir, entry);
        if (entry === 'node_modules' || entry === 'fl8_packages') continue;
        const stat = fs.statSync(full);
        if (stat.isDirectory()) {
          walk(full);
        } else {
          files.push(full);
        }
      }
    }

    walk(this.projectDir);
    return files;
  }

  // ─── list ──────────────────────────────────────────────────

  list(): PackageInfo[] {
    const manifest = this.readManifest();
    const lock = this.readLock();
    const result: PackageInfo[] = [];

    const allDeps = {
      ...manifest?.dependencies,
      ...manifest?.devDependencies,
    };

    for (const [name, versionRange] of Object.entries(allDeps)) {
      const locked = lock.packages[name];
      result.push({
        name,
        required: versionRange,
        installed: locked?.version ?? null,
        resolved: locked?.resolved ?? null,
      });
    }

    return result;
  }

  // ─── resolve (import 경로 → 실제 파일) ─────────────────────

  resolve(importPath: string, fromFile: string): string {
    const fromDir = path.dirname(fromFile);

    // 상대 경로
    if (importPath.startsWith('./') || importPath.startsWith('../')) {
      return path.resolve(fromDir, importPath);
    }

    // 패키지 이름
    const pkgPath = path.join(this.pkgDir, importPath, 'index.fl8');
    if (fs.existsSync(pkgPath)) return pkgPath;

    const pkgPath2 = path.join(this.pkgDir, importPath + '.fl8');
    if (fs.existsSync(pkgPath2)) return pkgPath2;

    throw new Error(`패키지를 찾을 수 없음: ${importPath}`);
  }
}

// ============================================================
// 빌트인 패키지 정의
// ============================================================

interface BuiltinPkg {
  version: string;
  description: string;
  source: string;
}

const BUILTIN_PACKAGES: Map<string, BuiltinPkg> = new Map([
  ['fl8-math', {
    version: '1.0.0',
    description: '수학 함수 확장',
    source: `
// fl8-math — 수학 함수 라이브러리
fn abs(x) { if x < 0 { return -x } return x }
fn max(a, b) { if a > b { return a } return b }
fn min(a, b) { if a < b { return a } return b }
fn clamp(x, lo, hi) { return max(lo, min(hi, x)) }
fn lerp(a, b, t) { return a + (b - a) * t }
print("fl8-math 로드 완료")
`.trim(),
  }],
  ['fl8-tensor', {
    version: '1.0.0',
    description: 'Tensor 유틸리티',
    source: `
// fl8-tensor — Tensor 헬퍼
fn eye(n) {
  let result = zeros(n, n)
  let i = 0
  while i < n {
    result[i][i] = 1.0
    i = i + 1
  }
  return result
}
print("fl8-tensor 로드 완료")
`.trim(),
  }],
  ['fl8-metrics', {
    version: '1.0.0',
    description: 'ML 평가 지표',
    source: `
// fl8-metrics — ML 평가 함수
fn accuracy(preds, labels) {
  let correct = 0
  let i = 0
  while i < len(preds) {
    if preds[i] == labels[i] { correct = correct + 1 }
    i = i + 1
  }
  return correct / len(preds)
}
print("fl8-metrics 로드 완료")
`.trim(),
  }],
]);

// ============================================================
// 타입 & 헬퍼
// ============================================================

export interface InstallResult {
  name: string;
  version: string;
  resolved: string;
  integrity: string;
  count?: number;
}

export interface PublishOptions {
  registry?: string;
  include?: string[];
  tag?: string;
}

export interface PublishResult {
  name: string;
  version: string;
  registry: string;
  files: number;
  success: boolean;
  url: string;
}

export interface PackageInfo {
  name: string;
  required: string;
  installed: string | null;
  resolved: string | null;
}

function simpleHash(s: string): string {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) - h + s.charCodeAt(i)) | 0;
  }
  return 'sha256-' + Math.abs(h).toString(16).padStart(8, '0');
}

function copyDir(src: string, dest: string, exts: string[]) {
  for (const entry of fs.readdirSync(src)) {
    const srcFile = path.join(src, entry);
    const destFile = path.join(dest, entry);
    const stat = fs.statSync(srcFile);

    if (stat.isDirectory()) {
      fs.mkdirSync(destFile, { recursive: true });
      copyDir(srcFile, destFile, exts);
    } else if (exts.some(e => entry.endsWith(e))) {
      fs.copyFileSync(srcFile, destFile);
    }
  }
}

