// FreeLang v8 ML — Python 브릿지 (Phase 6)
// JSON 직렬화 기반 Python/NumPy 데이터 교환

import { execSync, spawnSync } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';

// ============================================================
// 타입 정의
// ============================================================

export interface NumpyArray {
  shape: number[];
  dtype: string;        // 'float32', 'float64', 'int32', 'int64'
  data: number[];       // flat 1D 배열
}

export interface TorchTensor {
  shape: number[];
  dtype: string;
  requires_grad: boolean;
  data: number[];
}

export interface BridgeResult<T = any> {
  success: boolean;
  data?: T;
  error?: string;
  stdout?: string;
  stderr?: string;
}

// ============================================================
// FL8Tensor → NumpyArray 변환
// ============================================================

export function fl8ToNumpy(data: number[], shape: number[]): NumpyArray {
  const total = shape.reduce((a, b) => a * b, 1);
  if (data.length !== total) {
    throw new Error(`shape ${shape} 총 원소 수(${total})와 데이터 수(${data.length}) 불일치`);
  }
  return { shape, dtype: 'float32', data };
}

export function numpyToFl8(arr: NumpyArray): { data: number[]; shape: number[] } {
  return { data: arr.data, shape: arr.shape };
}

export function fl8ToTorch(data: number[], shape: number[], requires_grad = false): TorchTensor {
  return {
    shape,
    dtype: 'float32',
    requires_grad,
    data,
  };
}

export function torchToFl8(tensor: TorchTensor): { data: number[]; shape: number[] } {
  return { data: tensor.data, shape: tensor.shape };
}

// ============================================================
// JSON 브릿지 직렬화/역직렬화
// ============================================================

export interface BridgePayload {
  op: string;           // 'eval', 'forward', 'convert', 'script'
  inputs?: NumpyArray[];
  code?: string;        // 실행할 Python 코드
  model_path?: string;  // .pt 파일 경로
  kwargs?: Record<string, any>;
}

export interface BridgeResponse {
  success: boolean;
  outputs?: NumpyArray[];
  scalars?: Record<string, number>;
  strings?: Record<string, string>;
  error?: string;
}

export function serializePayload(payload: BridgePayload): string {
  return JSON.stringify(payload);
}

export function deserializeResponse(json: string): BridgeResponse {
  return JSON.parse(json);
}

// ============================================================
// Python 브릿지 클라이언트
// ============================================================

export class PythonBridge {
  private pythonBin: string;
  private bridgeScript: string;

  constructor(options: { python?: string; bridgeScript?: string } = {}) {
    this.pythonBin = options.python ?? this.detectPython();
    this.bridgeScript = options.bridgeScript ?? this.defaultBridgeScript();
  }

  private detectPython(): string {
    for (const bin of ['python3', 'python']) {
      try {
        const result = spawnSync(bin, ['--version'], { encoding: 'utf-8' });
        if (result.status === 0) return bin;
      } catch { /* skip */ }
    }
    return 'python3'; // fallback
  }

  private defaultBridgeScript(): string {
    return path.join(__dirname, '..', '..', 'bridge', 'fl8_bridge.py');
  }

  // Python 사용 가능 여부 확인
  isAvailable(): boolean {
    const result = spawnSync(this.pythonBin, ['--version'], { encoding: 'utf-8' });
    return result.status === 0;
  }

  // Python 버전 반환
  version(): string {
    try {
      const result = spawnSync(this.pythonBin, ['--version'], { encoding: 'utf-8' });
      return (result.stdout || result.stderr || '').trim();
    } catch {
      return 'unknown';
    }
  }

  // NumPy 사용 가능 여부
  hasNumpy(): boolean {
    const result = spawnSync(
      this.pythonBin,
      ['-c', 'import numpy; print(numpy.__version__)'],
      { encoding: 'utf-8' }
    );
    return result.status === 0;
  }

  // PyTorch 사용 가능 여부
  hasTorch(): boolean {
    const result = spawnSync(
      this.pythonBin,
      ['-c', 'import torch; print(torch.__version__)'],
      { encoding: 'utf-8' }
    );
    return result.status === 0;
  }

  // ─── Python 코드 실행 ───────────────────────────────────────

  eval(code: string): BridgeResult<Record<string, any>> {
    const tmpFile = path.join(os.tmpdir(), `fl8_bridge_${Date.now()}.json`);

    // 결과를 JSON으로 출력하는 wrapper 코드
    const wrappedCode = `
import json, sys

_fl8_result = {}

try:
${code.split('\n').map(l => '    ' + l).join('\n')}

except Exception as e:
    print(json.dumps({"success": False, "error": str(e)}))
    sys.exit(0)

print(json.dumps({"success": True, "result": _fl8_result}))
`.trim();

    const result = spawnSync(this.pythonBin, ['-c', wrappedCode], {
      encoding: 'utf-8',
      timeout: 30000,
    });

    if (result.status !== 0) {
      return {
        success: false,
        error: result.stderr || '실행 실패',
        stderr: result.stderr,
      };
    }

    try {
      const parsed = JSON.parse(result.stdout.trim());
      return {
        success: parsed.success,
        data: parsed.result,
        error: parsed.error,
        stdout: result.stdout,
      };
    } catch {
      return { success: true, data: {}, stdout: result.stdout };
    }
  }

  // ─── NumPy 배열 변환 ────────────────────────────────────────

  numpyEval(code: string, inputs: Record<string, NumpyArray> = {}): BridgeResult<Record<string, NumpyArray>> {
    if (!this.hasNumpy()) {
      return { success: false, error: 'NumPy가 설치되어 있지 않습니다' };
    }

    // 입력 배열 Python 코드로 변환
    const inputCode = Object.entries(inputs).map(([name, arr]) => {
      return `${name} = np.array(${JSON.stringify(arr.data)}, dtype=np.${arr.dtype}).reshape(${JSON.stringify(arr.shape)})`;
    }).join('\n');

    const fullCode = `
import numpy as np
import json, sys

# 입력 배열
${inputCode}

# 사용자 코드
${code}

# 출력 배열 직렬화
_outputs = {}
for _k, _v in list(locals().items()):
    if isinstance(_v, np.ndarray) and not _k.startswith('_'):
        _outputs[_k] = {
            "shape": list(_v.shape),
            "dtype": str(_v.dtype),
            "data": _v.flatten().tolist()
        }

print(json.dumps({"success": True, "outputs": _outputs}))
`.trim();

    const result = spawnSync(this.pythonBin, ['-c', fullCode], {
      encoding: 'utf-8',
      timeout: 30000,
    });

    if (result.status !== 0) {
      return { success: false, error: result.stderr };
    }

    try {
      const parsed = JSON.parse(result.stdout.trim());
      return {
        success: parsed.success,
        data: parsed.outputs,
        stderr: result.stderr,
      };
    } catch (e: any) {
      return { success: false, error: `JSON 파싱 실패: ${e.message}`, stdout: result.stdout };
    }
  }

  // ─── PyTorch 모델 실행 ──────────────────────────────────────

  torchForward(modelPath: string, inputData: number[], inputShape: number[]): BridgeResult<NumpyArray> {
    if (!this.hasTorch()) {
      return { success: false, error: 'PyTorch가 설치되어 있지 않습니다' };
    }

    const code = `
import torch
import json, sys

model = torch.load(${JSON.stringify(modelPath)}, map_location='cpu')
model.eval()

x = torch.tensor(${JSON.stringify(inputData)}, dtype=torch.float32).reshape(${JSON.stringify(inputShape)})
with torch.no_grad():
    out = model(x)

result = out.numpy().flatten().tolist()
shape = list(out.shape)
print(json.dumps({"success": True, "output": {"shape": shape, "dtype": "float32", "data": result}}))
`.trim();

    const result = spawnSync(this.pythonBin, ['-c', code], {
      encoding: 'utf-8',
      timeout: 60000,
    });

    if (result.status !== 0) {
      return { success: false, error: result.stderr };
    }

    try {
      const parsed = JSON.parse(result.stdout.trim());
      return { success: true, data: parsed.output };
    } catch {
      return { success: false, error: '응답 파싱 실패', stdout: result.stdout };
    }
  }

  // ─── FL8 → PyTorch weight 변환 ─────────────────────────────

  exportWeights(weights: Record<string, number[][]>, outputPath: string): BridgeResult {
    if (!this.hasTorch()) {
      return { success: false, error: 'PyTorch 없음' };
    }

    const weightsJson = JSON.stringify(weights);

    const code = `
import torch, json

weights = json.loads(${JSON.stringify(weightsJson)})
state_dict = {}
for name, data in weights.items():
    tensor = torch.tensor(data, dtype=torch.float32)
    state_dict[name] = tensor

torch.save(state_dict, ${JSON.stringify(outputPath)})
print(json.dumps({"success": True, "path": ${JSON.stringify(outputPath)}}))
`.trim();

    const result = spawnSync(this.pythonBin, ['-c', code], {
      encoding: 'utf-8',
      timeout: 30000,
    });

    if (result.status !== 0) {
      return { success: false, error: result.stderr };
    }

    return { success: true, data: { path: outputPath } };
  }
}

