// FreeLang v8 ML — WASM 타겟 (Phase 6)
// 브라우저에서 FL8 ML 실행을 위한 번들러

import * as fs from 'fs';
import * as path from 'path';

// ============================================================
// WASM 타겟 설정
// ============================================================

export interface WasmTargetConfig {
  entry: string;           // 진입점 .fl8 파일
  output: string;          // 출력 디렉토리
  minify?: boolean;
  embedRuntime?: boolean;  // FL8 런타임 인라인 포함
  exportFunctions?: string[]; // WASM으로 export할 함수 이름
  targetEnv?: 'browser' | 'node' | 'worker';
}

export interface WasmBuildResult {
  success: boolean;
  files: string[];
  size: number;
  error?: string;
}

// ============================================================
// JS 번들 생성 (WASM 없이 JS로 FL8 실행)
// ============================================================

export class WasmTarget {
  constructor(private config: WasmTargetConfig) {}

  build(): WasmBuildResult {
    try {
      if (!fs.existsSync(this.config.output)) {
        fs.mkdirSync(this.config.output, { recursive: true });
      }

      const files: string[] = [];

      // 1. FL8 런타임 번들 생성
      const runtimeBundle = this.generateRuntimeBundle();
      const runtimePath = path.join(this.config.output, 'fl8-runtime.js');
      fs.writeFileSync(runtimePath, runtimeBundle);
      files.push(runtimePath);

      // 2. 진입점 .fl8 읽기
      const entrySource = fs.readFileSync(this.config.entry, 'utf-8');
      const entryEncoded = Buffer.from(entrySource).toString('base64');

      // 3. 메인 번들 생성
      const mainBundle = this.generateMainBundle(entryEncoded);
      const mainPath = path.join(this.config.output, 'fl8-app.js');
      fs.writeFileSync(mainPath, mainBundle);
      files.push(mainPath);

      // 4. HTML 래퍼 (브라우저 타겟인 경우)
      if (this.config.targetEnv !== 'node' && this.config.targetEnv !== 'worker') {
        const htmlPath = path.join(this.config.output, 'index.html');
        fs.writeFileSync(htmlPath, this.generateHTML());
        files.push(htmlPath);
      }

      // 5. Worker 래퍼 (Web Worker)
      if (this.config.targetEnv === 'worker') {
        const workerPath = path.join(this.config.output, 'fl8-worker.js');
        fs.writeFileSync(workerPath, this.generateWorkerBundle(entryEncoded));
        files.push(workerPath);
      }

      // 6. TypeScript 타입 선언
      const dtsPath = path.join(this.config.output, 'fl8-runtime.d.ts');
      fs.writeFileSync(dtsPath, this.generateTypes());
      files.push(dtsPath);

      const totalSize = files.reduce((s, f) => s + fs.statSync(f).size, 0);

      return { success: true, files, size: totalSize };
    } catch (e: any) {
      return { success: false, files: [], size: 0, error: e.message };
    }
  }

  // ─── 런타임 번들 (FL8 핵심 런타임을 JS로) ───────────────────

  private generateRuntimeBundle(): string {
    return `
// FL8 Runtime — Browser Bundle (Phase 6)
// FreeLang v8 ML WASM-compatible JavaScript Runtime
(function(global) {
'use strict';

// ─── Value (AutoDiff) ─────────────────────────────────────
class Value {
  constructor(data) {
    this.data = data;
    this.grad = 0;
    this._backward = () => {};
    this._prev = [];
  }

  static from(data) { return new Value(data); }

  add(other) {
    const out = new Value(this.data + other.data);
    out._prev = [this, other];
    out._backward = () => {
      this.grad += out.grad;
      other.grad += out.grad;
    };
    return out;
  }

  mul(other) {
    const out = new Value(this.data * other.data);
    out._prev = [this, other];
    out._backward = () => {
      this.grad += other.data * out.grad;
      other.grad += this.data * out.grad;
    };
    return out;
  }

  relu() {
    const out = new Value(Math.max(0, this.data));
    out._prev = [this];
    out._backward = () => {
      this.grad += (out.data > 0 ? 1 : 0) * out.grad;
    };
    return out;
  }

  backward() {
    const topo = [];
    const visited = new Set();
    const build = (v) => {
      if (!visited.has(v)) {
        visited.add(v);
        for (const p of v._prev) build(p);
        topo.push(v);
      }
    };
    build(this);
    this.grad = 1;
    for (let i = topo.length - 1; i >= 0; i--) {
      topo[i]._backward();
    }
  }
}

// ─── Tensor 연산 ──────────────────────────────────────────
function fl8_zeros(rows, cols) {
  if (cols === undefined) return Array(rows).fill(0);
  return Array.from({length: rows}, () => Array(cols).fill(0));
}

function fl8_ones(rows, cols) {
  if (cols === undefined) return Array(rows).fill(1);
  return Array.from({length: rows}, () => Array(cols).fill(1));
}

function fl8_matmul(A, B) {
  const m = A.length, k = A[0].length, n = B[0].length;
  return Array.from({length: m}, (_, i) =>
    Array.from({length: n}, (_, j) => {
      let s = 0;
      for (let p = 0; p < k; p++) s += A[i][p] * B[p][j];
      return s;
    })
  );
}

function fl8_shape(arr) {
  const s = [];
  let cur = arr;
  while (Array.isArray(cur)) { s.push(cur.length); cur = cur[0]; }
  return s;
}

// ─── MiniGPT (축약 버전) ──────────────────────────────────
class MiniGPT_Browser {
  constructor(vocabSize, dModel, numHeads, numLayers, maxSeqLen) {
    this.config = {vocabSize, dModel, numHeads, numLayers, maxSeqLen};
    // 간소화: 단순 행렬 기반 언어 모델
    const scale = Math.sqrt(2 / dModel);
    this.embed = Array.from({length: vocabSize}, () =>
      Array.from({length: dModel}, () => (Math.random() * 2 - 1) * scale)
    );
    this.lmHead = Array.from({length: dModel}, () =>
      Array.from({length: vocabSize}, () => (Math.random() * 2 - 1) * scale * 0.1)
    );
  }

  forward(ids) {
    return ids.map(id => {
      const emb = this.embed[id] ?? this.embed[0];
      // 간소화 forward: embed @ lmHead
      return emb.map((_, j) => {
        let s = 0;
        for (let k = 0; k < emb.length; k++) s += emb[k] * this.lmHead[k][j];
        return s;
      });
    });
  }

  predict(ids) {
    const logits = this.forward(ids);
    const last = logits[logits.length - 1];
    return last.reduce((best, v, i) => v > last[best] ? i : best, 0);
  }

  generate(seedIds, maxNew) {
    let ids = [...seedIds];
    for (let i = 0; i < maxNew; i++) {
      ids.push(this.predict(ids.slice(-this.config.maxSeqLen)));
    }
    return ids;
  }
}

// ─── CharTokenizer (브라우저) ─────────────────────────────
class CharTokenizer_Browser {
  constructor() {
    this.charToId = {};
    this.idToChar = {};
    this.vocabSize = 4; // PAD UNK BOS EOS
  }

  fit(text) {
    const chars = [...new Set(text.split(''))].sort();
    for (const c of chars) {
      if (!(c in this.charToId)) {
        this.charToId[c] = this.vocabSize;
        this.idToChar[this.vocabSize] = c;
        this.vocabSize++;
      }
    }
  }

  encode(text, addBos = false, addEos = false) {
    const ids = [];
    if (addBos) ids.push(2);
    for (const c of text) ids.push(this.charToId[c] ?? 1);
    if (addEos) ids.push(3);
    return ids;
  }

  decode(ids) {
    return ids.map(id => this.idToChar[id] ?? '').join('');
  }
}

// ─── FL8 인터프리터 (브라우저 지원 서브셋) ────────────────
class FL8Interpreter {
  constructor() {
    this.output = [];
    this.env = {
      print: (...args) => {
        const line = args.map(a => this._display(a)).join(' ');
        this.output.push(line);
        if (typeof console !== 'undefined') console.log('[FL8]', line);
        return null;
      },
      zeros: fl8_zeros,
      ones: fl8_ones,
      matmul: fl8_matmul,
      shape: fl8_shape,
      len: (a) => Array.isArray(a) ? a.length : 0,
      MiniGPT: (vocab, dm, nh, nl, ms) => new MiniGPT_Browser(vocab, dm, nh, nl, ms),
      CharTokenizer: () => new CharTokenizer_Browser(),
      Math: Math,
    };
  }

  _display(v) {
    if (v === null || v === undefined) return 'null';
    if (typeof v === 'object' && v instanceof MiniGPT_Browser) return '[MiniGPT]';
    if (typeof v === 'object' && v instanceof CharTokenizer_Browser) return '[CharTokenizer]';
    if (Array.isArray(v)) return JSON.stringify(v);
    return String(v);
  }

  getOutput() { return this.output.join('\\n'); }
}

// ─── 공개 API ─────────────────────────────────────────────
const FL8Runtime = {
  Value,
  MiniGPT: MiniGPT_Browser,
  CharTokenizer: CharTokenizer_Browser,
  FL8Interpreter,
  tensor: {
    zeros: fl8_zeros,
    ones: fl8_ones,
    matmul: fl8_matmul,
    shape: fl8_shape,
  },
  version: '8.0.0-wasm',
};

// 환경별 export
if (typeof module !== 'undefined' && module.exports) {
  module.exports = FL8Runtime;
} else if (typeof define === 'function' && define.amd) {
  define(FL8Runtime);
} else {
  global.FL8Runtime = FL8Runtime;
}

})(typeof globalThis !== 'undefined' ? globalThis : typeof window !== 'undefined' ? window : global);
`.trim();
  }

  // ─── 메인 번들 ──────────────────────────────────────────────

  private generateMainBundle(entryBase64: string): string {
    const exports = this.config.exportFunctions ?? [];
    const exportsCode = exports.length > 0
      ? `\n// Export functions\nconst FL8_EXPORTS = { ${exports.map(f => `${f}: env.${f}`).join(', ')} };`
      : '';

    return `
// FL8 App Bundle
// Generated by FreeLang v8 ML WASM Target
'use strict';

(function() {
  const FL8_SOURCE = atob('${entryBase64}');

  // FL8 소스를 런타임에서 실행
  async function runFL8App(containerId) {
    const container = document.getElementById(containerId);
    if (!container) {
      console.error('[FL8] 컨테이너를 찾을 수 없음:', containerId);
      return;
    }

    const output = [];
    const runtime = window.FL8Runtime;
    if (!runtime) {
      container.textContent = '오류: FL8 런타임이 로드되지 않았습니다';
      return;
    }

    const interp = new runtime.FL8Interpreter();

    // 소스 실행 (간소화: eval 기반)
    try {
      // 실제 구현에서는 FL8 파서/인터프리터 사용
      container.textContent = '실행 중...';
      await new Promise(resolve => setTimeout(resolve, 10));
      container.textContent = interp.getOutput() || 'FL8 앱 실행됨';
    } catch (e) {
      container.textContent = '오류: ' + e.message;
    }
  }

  ${exportsCode}

  window.runFL8App = runFL8App;
  window.FL8_SOURCE = FL8_SOURCE;
})();
`.trim();
  }

  // ─── Web Worker 번들 ────────────────────────────────────────

  private generateWorkerBundle(entryBase64: string): string {
    return `
