#!/usr/bin/env ts-node
// FreeLang v8 ML — .fl8 파일 실행기 (fl8 CLI)
// Phase 6: install/publish/build 서브커맨드 추가

import * as fs from "fs";
import * as path from "path";
import { Lexer } from "./lexer/lexer";
import { Parser } from "./parser/parser";
import { Interpreter } from "./runtime/interpreter";
import { PackageManager } from "./pkg/package-manager";
import { buildForBrowser, buildForWorker } from "./wasm/wasm_target";
import { PythonBridge } from "./bridge/python_bridge";

const VERSION = "8.0.0";

function printHelp() {
  console.log(`FreeLang v8 ML — fl8 CLI v${VERSION}

사용법:
  fl8 <파일.fl8>                  .fl8 파일 실행
  fl8 -e '<코드>'                 인라인 코드 실행

패키지 관리:
  fl8 init [이름]                 fl8.json 초기화
  fl8 install                     모든 의존성 설치
  fl8 install <패키지> [버전]     특정 패키지 설치
  fl8 publish                     패키지 배포
  fl8 list                        설치된 패키지 목록

빌드:
  fl8 build browser <입력.fl8> <출력폴더>   브라우저 번들 생성
  fl8 build worker  <입력.fl8> <출력폴더>   Web Worker 번들 생성

브릿지:
  fl8 python info                 Python 환경 정보
  fl8 python run <코드>           Python 코드 실행

옵션:
  --version, -v                   버전 출력
  --help, -h                      이 도움말 출력`);
}

function main() {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    printHelp();
    process.exit(1);
  }

  const cmd = args[0];

  // 버전/도움말
  if (cmd === "--version" || cmd === "-v") {
    console.log(`fl8 v${VERSION}`);
    return;
  }
  if (cmd === "--help" || cmd === "-h") {
    printHelp();
    return;
  }

  // ─── 패키지 관리 ───────────────────────────────────────────

  if (cmd === "init") {
    const pm = new PackageManager();
