console.log('\n[3] NumPy 호환 인터페이스 (JS 구현)');

test('numpy.zeros: shape 검증', () => {
  const arr = numpy.zeros([3, 4]);
  assert(arr.shape[0] === 3 && arr.shape[1] === 4, `shape: ${arr.shape}`);
  assert(arr.data.every(v => v === 0), 'zeros not all 0');
});

test('numpy.ones: 모든 원소 1', () => {
  const arr = numpy.ones([2, 3]);
  assert(arr.data.every(v => v === 1), 'ones not all 1');
  assert(arr.shape.length === 2, `ndim: ${arr.shape.length}`);
});

test('numpy.array: shape 추론', () => {
  const arr = numpy.array([1, 2, 3, 4, 5]);
  assert(arr.shape[0] === 5, `shape: ${arr.shape}`);
  assert(arr.data[2] === 3, `data[2]: ${arr.data[2]}`);
});

test('numpy.matmul: 2D 행렬 곱', () => {
  // [2,3] @ [3,2] = [2,2]
  const A = numpy.array([1, 2, 3, 4, 5, 6], [2, 3]);
  const B = numpy.array([7, 8, 9, 10, 11, 12], [3, 2]);
  const C = numpy.matmul(A, B);
  assert(C.shape[0] === 2 && C.shape[1] === 2, `shape: ${C.shape}`);
  // [1*7+2*9+3*11, 1*8+2*10+3*12] = [58, 64]
  assert(C.data[0] === 58, `C[0][0]: ${C.data[0]}`);
  assert(C.data[1] === 64, `C[0][1]: ${C.data[1]}`);
});

test('numpy.transpose: 행렬 전치', () => {
  const A = numpy.array([1, 2, 3, 4, 5, 6], [2, 3]);
  const At = numpy.transpose(A);
  assert(At.shape[0] === 3 && At.shape[1] === 2, `shape: ${At.shape}`);
  assert(At.data[0] === 1, `At[0][0]: ${At.data[0]}`);
  assert(At.data[1] === 4, `At[0][1]: ${At.data[1]}`);  // 전치 후 4
});

test('numpy.reshape: 재형성', () => {
  const A = numpy.array([1, 2, 3, 4, 5, 6], [6]);
  const B = numpy.reshape(A, [2, 3]);
  assert(B.shape[0] === 2 && B.shape[1] === 3, `shape: ${B.shape}`);
  assert(B.data.length === 6, `data.length: ${B.data.length}`);
});

test('numpy.reshape: shape 불일치 오류', () => {
  let threw = false;
  try { numpy.reshape(numpy.zeros([6]), [2, 4]); } catch { threw = true; }
  assert(threw, 'reshape 오류 없음');
});

test('numpy.add: 스칼라 덧셈', () => {
  const A = numpy.array([1, 2, 3]);
  const B = numpy.add(A, 1);
  assert(B.data[0] === 2 && B.data[2] === 4, `add scalar: ${B.data}`);
});

test('numpy.mul: 원소별 곱', () => {
  const A = numpy.array([1, 2, 3]);
  const B = numpy.array([2, 3, 4]);
  const C = numpy.mul(A, B);
  assert(C.data[0] === 2 && C.data[1] === 6 && C.data[2] === 12, `mul: ${C.data}`);
});

test('numpy.relu: 음수 → 0', () => {
  const A = numpy.array([-1, 0, 1, 2]);
  const R = numpy.relu(A);
  assert(R.data[0] === 0, `relu[-1]: ${R.data[0]}`);
  assert(R.data[2] === 1, `relu[1]: ${R.data[2]}`);
});

test('numpy.sigmoid: 범위 (0,1)', () => {
  const A = numpy.array([-10, 0, 10]);
  const S = numpy.sigmoid(A);
  assert(S.data[0] < 0.01, `sigmoid(-10): ${S.data[0]}`);
  assert(Math.abs(S.data[1] - 0.5) < 0.001, `sigmoid(0): ${S.data[1]}`);
  assert(S.data[2] > 0.99, `sigmoid(10): ${S.data[2]}`);
});

test('numpy.mean: 평균', () => {
  const A = numpy.array([1, 2, 3, 4]);
  const m = numpy.mean(A);
  assert(Math.abs(m - 2.5) < 1e-6, `mean: ${m}`);
});

test('numpy.toString: 1D 출력', () => {
  const A = numpy.array([1, 2, 3]);
  const s = numpy.toString(A);
  assert(s.includes('array(['), `format: ${s}`);
});

test('numpy.toString: 2D 출력', () => {
  const A = numpy.array([1, 2, 3, 4], [2, 2]);
  const s = numpy.toString(A);
  assert(s.includes('array([') && s.includes('['), `format: ${s}`);
});

