// FreeLang v8 ML — Phase 6 생태계 테스트
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import { PackageManager, FL8Manifest } from '../src/pkg/package-manager';
import {
  fl8ToNumpy, numpyToFl8, fl8ToTorch, torchToFl8,
  PythonBridge, numpy, NumpyArray, generateBridgeScript,
} from '../src/bridge/python_bridge';
import { buildForBrowser, buildForWorker, WasmTarget } from '../src/wasm/wasm_target';
import { Lexer } from '../src/lexer/lexer';
import { Parser } from '../src/parser/parser';
import { Interpreter } from '../src/runtime/interpreter';

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
  }
}

function assert(cond: boolean, msg: string) {
  if (!cond) throw new Error(msg);
}

function run(src: string) {
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  if (errors.length > 0) throw new Error(`파서: ${errors[0].message}`);
  new Interpreter().run(program);
}

// 임시 디렉토리 생성
function makeTmpDir(): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'fl8-test-'));
  return dir;
}

function cleanupDir(dir: string) {
  try {
    fs.rmSync(dir, { recursive: true, force: true });
  } catch { /* ignore */ }
}

// ======================================================
// 1. PackageManager
// ======================================================
console.log('\n[1] PackageManager — fl8.json 기반 패키지 시스템');

let tmpDir1 = '';
test('init: fl8.json 생성', () => {
  tmpDir1 = makeTmpDir();
  const pm = new PackageManager(tmpDir1);
  const manifest = pm.init({ name: 'test-pkg', version: '1.0.0' });
  assert(manifest.name === 'test-pkg', `name: ${manifest.name}`);
  assert(manifest.version === '1.0.0', `version: ${manifest.version}`);
  assert(fs.existsSync(path.join(tmpDir1, 'fl8.json')), 'fl8.json 없음');
});

test('readManifest: 저장된 manifest 읽기', () => {
  const pm = new PackageManager(tmpDir1);
  const manifest = pm.readManifest();
  assert(manifest !== null, 'manifest null');
  assert(manifest!.name === 'test-pkg', `name: ${manifest!.name}`);
  assert(manifest!.ml?.framework === 'freelang-v8', `framework: ${manifest!.ml?.framework}`);
});

test('readLock: 초기 lock 파일 읽기', () => {
  const pm = new PackageManager(tmpDir1);
  const lock = pm.readLock();
  assert(lock.version === 1, `version: ${lock.version}`);
  assert(typeof lock.packages === 'object', 'packages 없음');
});

test('init: 중복 호출 오류', () => {
  const pm = new PackageManager(tmpDir1);
  let threw = false;
  try { pm.init(); } catch { threw = true; }
  assert(threw, '중복 init 오류 없음');
});

test('install: 빌트인 패키지 설치', () => {
  const pm = new PackageManager(tmpDir1);
  const result = pm.install('fl8-math');
  assert(result.name === 'fl8-math', `name: ${result.name}`);
  assert(result.version === '1.0.0', `version: ${result.version}`);
  const pkgPath = path.join(tmpDir1, 'fl8_packages', 'fl8-math', 'index.fl8');
  assert(fs.existsSync(pkgPath), `패키지 파일 없음: ${pkgPath}`);
});

test('install: manifest에 dependency 추가', () => {
  const pm = new PackageManager(tmpDir1);
  const manifest = pm.readManifest();
  assert(manifest?.dependencies?.['fl8-math'] !== undefined, 'fl8-math dependency 없음');
});

test('install: lock 파일 업데이트', () => {
  const pm = new PackageManager(tmpDir1);
  const lock = pm.readLock();
  assert(lock.packages['fl8-math'] !== undefined, 'lock에 fl8-math 없음');
  assert(lock.packages['fl8-math'].version === '1.0.0', `lock version: ${lock.packages['fl8-math'].version}`);
});

test('install: fl8-tensor 빌트인 설치', () => {
  const pm = new PackageManager(tmpDir1);
  const result = pm.install('fl8-tensor');
  assert(result.name === 'fl8-tensor', `name: ${result.name}`);
});

test('install: fl8-metrics 빌트인 설치', () => {
  const pm = new PackageManager(tmpDir1);
  const result = pm.install('fl8-metrics');
  assert(result.name === 'fl8-metrics', `name: ${result.name}`);
});

test('list: 설치 패키지 목록', () => {
  const pm = new PackageManager(tmpDir1);
  const pkgs = pm.list();
  assert(pkgs.length >= 3, `패키지 수: ${pkgs.length}`);
  assert(pkgs.some(p => p.name === 'fl8-math'), 'fl8-math 없음');
  assert(pkgs.some(p => p.name === 'fl8-tensor'), 'fl8-tensor 없음');
});

test('publish: 패키지 배포 결과', () => {
  const pm = new PackageManager(tmpDir1);
  const result = pm.publish({ registry: 'test.gogs.kr/kim' });
  assert(result.success, '배포 실패');
  assert(result.name === 'test-pkg', `name: ${result.name}`);
  assert(result.version === '1.0.0', `version: ${result.version}`);
  assert(result.url.includes('test.gogs.kr'), `url: ${result.url}`);
});

test('resolve: 패키지 경로 해석', () => {
  const pm = new PackageManager(tmpDir1);
  const resolved = pm.resolve('fl8-math', path.join(tmpDir1, 'main.fl8'));
  assert(resolved.includes('fl8-math') && resolved.includes('index.fl8'), `resolved: ${resolved}`);
});

test('install: GOGS 패키지 stub 설치', () => {
  const pm = new PackageManager(tmpDir1);
  const result = pm.install('gogs:kim/my-ml-pkg', '1.0.0');
  assert(result.name === 'my-ml-pkg', `name: ${result.name}`);
  assert(result.resolved.includes('gogs.dclub.kr'), `resolved: ${result.resolved}`);
});

// cleanup
if (tmpDir1) cleanupDir(tmpDir1);

// ======================================================
// 2. Python 브릿지 — 변환 함수
// ======================================================
console.log('\n[2] Python 브릿지 — 데이터 변환');

test('fl8ToNumpy: shape 일치', () => {
  const data = [1, 2, 3, 4, 5, 6];
  const arr = fl8ToNumpy(data, [2, 3]);
  assert(arr.shape[0] === 2 && arr.shape[1] === 3, `shape: ${arr.shape}`);
  assert(arr.dtype === 'float32', `dtype: ${arr.dtype}`);
  assert(arr.data.length === 6, `data.length: ${arr.data.length}`);
});

test('fl8ToNumpy: shape 불일치 오류', () => {
  let threw = false;
  try { fl8ToNumpy([1, 2, 3], [2, 3]); } catch { threw = true; }
  assert(threw, 'shape 불일치 오류 없음');
});

test('numpyToFl8: 역변환', () => {
  const arr: NumpyArray = { shape: [3], dtype: 'float32', data: [1, 2, 3] };
  const { data, shape } = numpyToFl8(arr);
  assert(data.length === 3, `data: ${data.length}`);
  assert(shape[0] === 3, `shape: ${shape}`);
});

test('fl8ToTorch: requires_grad 기본값', () => {
  const t = fl8ToTorch([1, 2, 3, 4], [2, 2]);
  assert(t.requires_grad === false, `requires_grad: ${t.requires_grad}`);
  assert(t.dtype === 'float32', `dtype: ${t.dtype}`);
  assert(t.shape[0] === 2, `shape: ${t.shape}`);
});

test('fl8ToTorch: requires_grad true', () => {
  const t = fl8ToTorch([1, 2], [1, 2], true);
  assert(t.requires_grad === true, 'requires_grad 실패');
});

test('torchToFl8: 역변환', () => {
  const t = { shape: [2, 2], dtype: 'float32', requires_grad: false, data: [1, 2, 3, 4] };
  const { data, shape } = torchToFl8(t);
  assert(data.length === 4, `data: ${data.length}`);
  assert(shape[0] === 2, `shape: ${shape}`);
});

// ======================================================
// 3. NumPy 호환 인터페이스
// ======================================================
console.log('\n[3] NumPy 호환 인터페이스 (JS 구현)');

test('numpy.zeros: shape 검증', () => {
  const arr = numpy.zeros([3, 4]);
  assert(arr.shape[0] === 3 && arr.shape[1] === 4, `shape: ${arr.shape}`);
  assert(arr.data.every(v => v === 0), 'zeros not all 0');
});

test('numpy.ones: 모든 원소 1', () => {
  const arr = numpy.ones([2, 3]);
  assert(arr.data.every(v => v === 1), 'ones not all 1');
  assert(arr.shape.length === 2, `ndim: ${arr.shape.length}`);
});

test('numpy.array: shape 추론', () => {
  const arr = numpy.array([1, 2, 3, 4, 5]);
  assert(arr.shape[0] === 5, `shape: ${arr.shape}`);
  assert(arr.data[2] === 3, `data[2]: ${arr.data[2]}`);
});

test('numpy.matmul: 2D 행렬 곱', () => {
  // [2,3] @ [3,2] = [2,2]
  const A = numpy.array([1, 2, 3, 4, 5, 6], [2, 3]);
  const B = numpy.array([7, 8, 9, 10, 11, 12], [3, 2]);
  const C = numpy.matmul(A, B);
  assert(C.shape[0] === 2 && C.shape[1] === 2, `shape: ${C.shape}`);
  // [1*7+2*9+3*11, 1*8+2*10+3*12] = [58, 64]
  assert(C.data[0] === 58, `C[0][0]: ${C.data[0]}`);
  assert(C.data[1] === 64, `C[0][1]: ${C.data[1]}`);
});

test('numpy.transpose: 행렬 전치', () => {
  const A = numpy.array([1, 2, 3, 4, 5, 6], [2, 3]);
  const At = numpy.transpose(A);
  assert(At.shape[0] === 3 && At.shape[1] === 2, `shape: ${At.shape}`);
  assert(At.data[0] === 1, `At[0][0]: ${At.data[0]}`);
  assert(At.data[1] === 4, `At[0][1]: ${At.data[1]}`);  // 전치 후 4
});

test('numpy.reshape: 재형성', () => {
  const A = numpy.array([1, 2, 3, 4, 5, 6], [6]);
  const B = numpy.reshape(A, [2, 3]);
  assert(B.shape[0] === 2 && B.shape[1] === 3, `shape: ${B.shape}`);
  assert(B.data.length === 6, `data.length: ${B.data.length}`);
});

test('numpy.reshape: shape 불일치 오류', () => {
  let threw = false;
  try { numpy.reshape(numpy.zeros([6]), [2, 4]); } catch { threw = true; }
  assert(threw, 'reshape 오류 없음');
});

test('numpy.add: 스칼라 덧셈', () => {
  const A = numpy.array([1, 2, 3]);
  const B = numpy.add(A, 1);
  assert(B.data[0] === 2 && B.data[2] === 4, `add scalar: ${B.data}`);
});

test('numpy.mul: 원소별 곱', () => {
  const A = numpy.array([1, 2, 3]);
  const B = numpy.array([2, 3, 4]);
  const C = numpy.mul(A, B);
  assert(C.data[0] === 2 && C.data[1] === 6 && C.data[2] === 12, `mul: ${C.data}`);
});

test('numpy.relu: 음수 → 0', () => {
  const A = numpy.array([-1, 0, 1, 2]);
  const R = numpy.relu(A);
  assert(R.data[0] === 0, `relu[-1]: ${R.data[0]}`);
  assert(R.data[2] === 1, `relu[1]: ${R.data[2]}`);
});

test('numpy.sigmoid: 범위 (0,1)', () => {
  const A = numpy.array([-10, 0, 10]);
  const S = numpy.sigmoid(A);
  assert(S.data[0] < 0.01, `sigmoid(-10): ${S.data[0]}`);
  assert(Math.abs(S.data[1] - 0.5) < 0.001, `sigmoid(0): ${S.data[1]}`);
  assert(S.data[2] > 0.99, `sigmoid(10): ${S.data[2]}`);
});

test('numpy.mean: 평균', () => {
  const A = numpy.array([1, 2, 3, 4]);
  const m = numpy.mean(A);
