// FreeLang v8 ML - 자동미분 (Autograd)
import { Tensor } from './tensor';

type GradFn = () => void;

export class Value {
  data: number;
  grad: number = 0;
  private _backward: GradFn = () => {};
  private _prev: Set<Value>;

  constructor(data: number, prev: Value[] = []) {
    this.data = data;
    this._prev = new Set(prev);
  }

  add(other: Value): Value {
    const out = new Value(this.data + other.data, [this, other]);
    out._backward = () => {
      this.grad += out.grad;
      other.grad += out.grad;
    };
    return out;
  }

  mul(other: Value): Value {
    const out = new Value(this.data * other.data, [this, other]);
    out._backward = () => {
      this.grad += other.data * out.grad;
      other.grad += this.data * out.grad;
    };
    return out;
  }

  relu(): Value {
    const out = new Value(Math.max(0, this.data), [this]);
    out._backward = () => {
      this.grad += (out.data > 0 ? 1 : 0) * out.grad;
    };
    return out;
  }

  tanh(): Value {
    const t = Math.tanh(this.data);
    const out = new Value(t, [this]);
    out._backward = () => {
      this.grad += (1 - t * t) * out.grad;
    };
    return out;
  }

  pow(exp: number): Value {
    const out = new Value(Math.pow(this.data, exp), [this]);
    out._backward = () => {
      this.grad += exp * Math.pow(this.data, exp - 1) * out.grad;
    };
    return out;
  }

  backward(): void {
    // 위상 정렬 후 역전파
    const topo: Value[] = [];
    const visited = new Set<Value>();
    const build = (v: Value) => {
      if (!visited.has(v)) {
        visited.add(v);
        for (const p of v._prev) build(p);
        topo.push(v);
      }
    };
    build(this);
    this.grad = 1;
    for (const v of topo.reverse()) v._backward();
  }

  static from(n: number): Value { return new Value(n); }
}

