// FreeLang v8 ML - Tensor 1급 시민
// shape 타입 시스템 내장

export type Shape = number[];

export class Tensor {
  data: Float32Array;
  shape: Shape;
  strides: number[];

  constructor(shape: Shape, data?: Float32Array) {
    this.shape = shape;
    this.strides = computeStrides(shape);
    const size = shape.reduce((a, b) => a * b, 1);
    this.data = data ?? new Float32Array(size);
  }

  get rank(): number { return this.shape.length; }
  get size(): number { return this.data.length; }

  // 인덱싱
  get(...indices: number[]): number {
    return this.data[this.offset(indices)];
  }
  set(value: number, ...indices: number[]): void {
    this.data[this.offset(indices)] = value;
  }

  private offset(indices: number[]): number {
    return indices.reduce((acc, idx, i) => acc + idx * this.strides[i], 0);
  }

  // 기본 연산
  add(other: Tensor): Tensor {
    checkShape(this.shape, other.shape);
    const out = new Tensor(this.shape);
    for (let i = 0; i < this.size; i++) out.data[i] = this.data[i] + other.data[i];
    return out;
  }

  mul(other: Tensor): Tensor {
    checkShape(this.shape, other.shape);
    const out = new Tensor(this.shape);
    for (let i = 0; i < this.size; i++) out.data[i] = this.data[i] * other.data[i];
    return out;
  }

  matmul(other: Tensor): Tensor {
    if (this.rank !== 2 || other.rank !== 2) throw new Error("matmul: 2D tensor 필요");
    const [N, M] = this.shape;
    const [M2, K] = other.shape;
    if (M !== M2) throw new Error(`shape 불일치: [${N},${M}] x [${M2},${K}]`);
    const out = new Tensor([N, K]);
    for (let i = 0; i < N; i++)
      for (let k = 0; k < K; k++) {
        let sum = 0;
        for (let j = 0; j < M; j++) sum += this.get(i, j) * other.get(j, k);
        out.set(sum, i, k);
      }
    return out;
  }

  // 자동미분용 grad
  grad?: Tensor;
  requiresGrad: boolean = false;

  withGrad(): this {
    this.requiresGrad = true;
    this.grad = new Tensor(this.shape);
    return this;
  }

  static zeros(shape: Shape): Tensor { return new Tensor(shape); }
  static ones(shape: Shape): Tensor {
    const t = new Tensor(shape);
    t.data.fill(1);
    return t;
  }
  static randn(shape: Shape): Tensor {
    const t = new Tensor(shape);
    for (let i = 0; i < t.size; i++) t.data[i] = randn();
    return t;
  }
}

function computeStrides(shape: Shape): number[] {
  const strides = new Array(shape.length).fill(1);
  for (let i = shape.length - 2; i >= 0; i--)
    strides[i] = strides[i + 1] * shape[i + 1];
  return strides;
}

function checkShape(a: Shape, b: Shape): void {
  if (a.length !== b.length || a.some((v, i) => v !== b[i]))
    throw new Error(`shape 불일치: [${a}] vs [${b}]`);
}

function randn(): number {
  // Box-Muller
  const u = 1 - Math.random();
  const v = Math.random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

