// FreeLang v8 ML — 고성능 Tensor 연산 (Phase 7)
// Float32Array 기반 배치 연산 + 캐시 친화적 알고리즘

// ============================================================
// 타입
// ============================================================

export type Shape = number[];

// ============================================================
// 1. Tiled Matmul (캐시 친화적)
//    naïve: O(N*M*K) 캐시 미스 多
//    tiled: 블록 단위 처리로 L1 캐시 적중률 향상
// ============================================================

const TILE = 32;

export function matmulTiled(
  A: Float32Array, B: Float32Array,
  N: number, M: number, K: number,
  C?: Float32Array
): Float32Array {
  const out = C ?? new Float32Array(N * K);

  for (let i0 = 0; i0 < N; i0 += TILE) {
    for (let k0 = 0; k0 < K; k0 += TILE) {
      for (let j0 = 0; j0 < M; j0 += TILE) {
        const iEnd = Math.min(i0 + TILE, N);
        const kEnd = Math.min(k0 + TILE, K);
        const jEnd = Math.min(j0 + TILE, M);
        for (let i = i0; i < iEnd; i++) {
          const rowA = i * M;
          const rowC = i * K;
          for (let k = k0; k < kEnd; k++) {
            const rowB = j0 * K;  // B는 [M,K] → row j*K
            let s = 0;
            for (let j = j0; j < jEnd; j++) {
              s += A[rowA + j] * B[j * K + k];
            }
            out[rowC + k] += s;
          }
        }
      }
    }
  }
  return out;
}

// ============================================================
// 2. 배치 Matmul  [batch, N, M] @ [batch, M, K] → [batch, N, K]
// ============================================================

export function batchMatmul(
  A: Float32Array, shapeA: Shape,
  B: Float32Array, shapeB: Shape
): { data: Float32Array; shape: Shape } {
  const [batch, N, M] = shapeA;
  const [, M2, K] = shapeB;
  if (M !== M2) throw new Error(`batchMatmul shape 불일치: M=${M} vs M2=${M2}`);

  const out = new Float32Array(batch * N * K);
  const bStepA = N * M;
  const bStepB = M * K;
  const bStepC = N * K;

  for (let b = 0; b < batch; b++) {
    matmulTiled(
      A.subarray(b * bStepA, (b + 1) * bStepA),
      B.subarray(b * bStepB, (b + 1) * bStepB),
      N, M, K,
      out.subarray(b * bStepC, (b + 1) * bStepC)
    );
  }
  return { data: out, shape: [batch, N, K] };
}

// ============================================================
// 3. 원소별 연산 (SIMD-like: 4원소 루프 언롤)
// ============================================================

export function addInPlace(a: Float32Array, b: Float32Array): void {
  const n4 = Math.floor(a.length / 4) * 4;
  for (let i = 0; i < n4; i += 4) {
    a[i]     += b[i];
    a[i + 1] += b[i + 1];
    a[i + 2] += b[i + 2];
    a[i + 3] += b[i + 3];
  }
  for (let i = n4; i < a.length; i++) a[i] += b[i];
}

export function scaleInPlace(a: Float32Array, s: number): void {
  const n4 = Math.floor(a.length / 4) * 4;
  for (let i = 0; i < n4; i += 4) {
    a[i]     *= s;
    a[i + 1] *= s;
    a[i + 2] *= s;
    a[i + 3] *= s;
  }
  for (let i = n4; i < a.length; i++) a[i] *= s;
}

export function reluInPlace(a: Float32Array): void {
  for (let i = 0; i < a.length; i++) if (a[i] < 0) a[i] = 0;
}

export function sigmoidInPlace(a: Float32Array): void {
  for (let i = 0; i < a.length; i++) a[i] = 1 / (1 + Math.exp(-a[i]));
}

export function tanhInPlace(a: Float32Array): void {
  for (let i = 0; i < a.length; i++) a[i] = Math.tanh(a[i]);
}

export function dotProduct(a: Float32Array, b: Float32Array): number {
  const n4 = Math.floor(a.length / 4) * 4;
  let s0 = 0, s1 = 0, s2 = 0, s3 = 0;
  for (let i = 0; i < n4; i += 4) {
    s0 += a[i]     * b[i];
    s1 += a[i + 1] * b[i + 1];
    s2 += a[i + 2] * b[i + 2];
    s3 += a[i + 3] * b[i + 3];
  }
  let s = s0 + s1 + s2 + s3;
  for (let i = n4; i < a.length; i++) s += a[i] * b[i];
  return s;
}

// ============================================================
// 4. Softmax (수치 안정)
// ============================================================

export function softmax(logits: Float32Array, out?: Float32Array): Float32Array {
  const result = out ?? new Float32Array(logits.length);
  let max = -Infinity;
  for (let i = 0; i < logits.length; i++) if (logits[i] > max) max = logits[i];
  let sum = 0;
  for (let i = 0; i < logits.length; i++) {
    result[i] = Math.exp(logits[i] - max);
    sum += result[i];
  }
  const invSum = 1 / sum;
  for (let i = 0; i < result.length; i++) result[i] *= invSum;
  return result;
}

// ============================================================
// 5. LayerNorm (배치)
// ============================================================

export function layerNorm(
  x: Float32Array,    // [seq * d_model]
  gamma: Float32Array,
  beta: Float32Array,
  dModel: number,
  eps = 1e-5
): Float32Array {
  const out = new Float32Array(x.length);
  const seq = x.length / dModel;

  for (let s = 0; s < seq; s++) {
    const off = s * dModel;
    // mean
    let mean = 0;
    for (let i = 0; i < dModel; i++) mean += x[off + i];
    mean /= dModel;
    // variance
    let variance = 0;
    for (let i = 0; i < dModel; i++) {
      const d = x[off + i] - mean;
      variance += d * d;
    }
    variance /= dModel;
    const invStd = 1 / Math.sqrt(variance + eps);
    for (let i = 0; i < dModel; i++) {
      out[off + i] = gamma[i] * (x[off + i] - mean) * invStd + beta[i];
    }
  }
  return out;
}

// ============================================================
// 6. Embedding lookup (배치)
// ============================================================

export function embeddingLookup(
  ids: number[],
  table: Float32Array,  // [vocabSize, dModel]
  dModel: number,
  out?: Float32Array
): Float32Array {
  const result = out ?? new Float32Array(ids.length * dModel);
  for (let i = 0; i < ids.length; i++) {
    const src = ids[i] * dModel;
    const dst = i * dModel;
    result.set(table.subarray(src, src + dModel), dst);
  }
  return result;
}

// ============================================================
// 7. Cross-Entropy Loss (배치)
// ============================================================

export function crossEntropyLoss(
  logits: Float32Array,  // [seq, vocabSize]
  targets: number[],     // [seq]
  vocabSize: number
): { loss: number; grad: Float32Array } {
  const seq = targets.length;
  const grad = new Float32Array(seq * vocabSize);
  let totalLoss = 0;

  const probs = new Float32Array(vocabSize);
  for (let t = 0; t < seq; t++) {
    const off = t * vocabSize;
    softmax(logits.subarray(off, off + vocabSize), probs);
    totalLoss -= Math.log(probs[targets[t]] + 1e-10);
    // grad = p - one_hot(target)
    probs.forEach((p, i) => { grad[off + i] = p; });
    grad[off + targets[t]] -= 1;
  }

  // 평균
  const scale = 1 / seq;
  scaleInPlace(grad, scale);
  return { loss: totalLoss / seq, grad };
}

// ============================================================
// 8. Adam 옵티마이저 — Float32Array 기반 (GC 없음)
// ============================================================

export class AdamF32 {
  private m: Float32Array;
  private v: Float32Array;
  private t = 0;

  constructor(
    paramCount: number,
    public lr = 1e-3,
    public beta1 = 0.9,
    public beta2 = 0.999,
    public eps = 1e-8,
    public weightDecay = 0.0
  ) {
    this.m = new Float32Array(paramCount);
    this.v = new Float32Array(paramCount);
  }

  step(params: Float32Array, grads: Float32Array): void {
    this.t++;
    const bc1 = 1 - Math.pow(this.beta1, this.t);
    const bc2 = 1 - Math.pow(this.beta2, this.t);
    const lrCorr = this.lr * Math.sqrt(bc2) / bc1;

    for (let i = 0; i < params.length; i++) {
      const g = grads[i] + this.weightDecay * params[i];
      this.m[i] = this.beta1 * this.m[i] + (1 - this.beta1) * g;
      this.v[i] = this.beta2 * this.v[i] + (1 - this.beta2) * g * g;
      params[i] -= lrCorr * this.m[i] / (Math.sqrt(this.v[i]) + this.eps);
    }
  }

  zeroGrad(grads: Float32Array): void {
    grads.fill(0);
  }

  reset(): void {
    this.m.fill(0);
    this.v.fill(0);
    this.t = 0;
  }
}

// ============================================================
// 9. LR 스케줄러
// ============================================================

export interface LRScheduler {
  getLR(step: number): number;
}

// 코사인 어닐링
export class CosineScheduler implements LRScheduler {
  constructor(
    public baseLR: number,
    public minLR: number,
    public totalSteps: number,
    public warmupSteps = 0
  ) {}

  getLR(step: number): number {
    if (step < this.warmupSteps) {
      return this.baseLR * (step / Math.max(1, this.warmupSteps));
    }
    const progress = (step - this.warmupSteps) / Math.max(1, this.totalSteps - this.warmupSteps);
    const cosine = 0.5 * (1 + Math.cos(Math.PI * Math.min(progress, 1)));
    return this.minLR + (this.baseLR - this.minLR) * cosine;
  }
}

// 스텝 감소 (Step Decay)
export class StepDecayScheduler implements LRScheduler {
  constructor(
    public baseLR: number,
    public stepSize: number,
    public gamma = 0.1
  ) {}

  getLR(step: number): number {
    const epoch = Math.floor(step / this.stepSize);
    return this.baseLR * Math.pow(this.gamma, epoch);
  }
}

// ============================================================
// 10. 전치 (in-place 가능)
// ============================================================

export function transpose2D(
  A: Float32Array, N: number, M: number
): Float32Array {
  const out = new Float32Array(N * M);
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < M; j++) {
      out[j * N + i] = A[i * M + j];
    }
  }
  return out;
}

// ============================================================
// 11. 그래디언트 클리핑
// ============================================================

export function gradClipNorm(grads: Float32Array, maxNorm: number): number {
  let norm = 0;
  for (let i = 0; i < grads.length; i++) norm += grads[i] * grads[i];
  norm = Math.sqrt(norm);
  if (norm > maxNorm) {
    const scale = maxNorm / (norm + 1e-6);
    scaleInPlace(grads, scale);
  }
  return norm;
}

// ============================================================
// 12. 메모리 풀 (재사용 가능한 버퍼)
// ============================================================

export class BufferPool {
  private pool = new Map<number, Float32Array[]>();
  private allocated = 0;
  private reused = 0;

  acquire(size: number): Float32Array {
    const bucket = this.pool.get(size);
    if (bucket && bucket.length > 0) {
      this.reused++;
      return bucket.pop()!;
    }
    this.allocated++;
    return new Float32Array(size);
  }

  release(buf: Float32Array): void {
    const bucket = this.pool.get(buf.length) ?? [];
    bucket.push(buf);
    this.pool.set(buf.length, bucket);
  }

  stats(): { allocated: number; reused: number; pooled: number } {
    let pooled = 0;
    for (const v of this.pool.values()) pooled += v.length;
    return { allocated: this.allocated, reused: this.reused, pooled };
  }

  clear(): void {
    this.pool.clear();
    this.allocated = 0;
    this.reused = 0;
  }
}

export const globalPool = new BufferPool();

