// FreeLang v8 ML — 프로파일러 (Phase 7)
// 연산 단위 시간 측정 + 병목 리포트

// ============================================================
// 타입
// ============================================================

export interface OpRecord {
  name: string;
  calls: number;
  totalMs: number;
  minMs: number;
  maxMs: number;
  lastMs: number;
}

// ============================================================
// Profiler
// ============================================================

export class Profiler {
  private records = new Map<string, OpRecord>();
  private stack: Array<{ name: string; start: number }> = [];
  enabled: boolean;

  constructor(enabled = true) {
    this.enabled = enabled;
  }

  // 연산 시작
  begin(name: string): void {
    if (!this.enabled) return;
    this.stack.push({ name, start: performance.now() });
  }

  // 연산 종료
  end(name?: string): number {
    if (!this.enabled) return 0;
    const frame = this.stack.pop();
    if (!frame) return 0;
    const opName = name ?? frame.name;
    const elapsed = performance.now() - frame.start;

    const rec = this.records.get(opName) ?? {
      name: opName, calls: 0, totalMs: 0,
      minMs: Infinity, maxMs: 0, lastMs: 0,
    };
    rec.calls++;
    rec.totalMs += elapsed;
    rec.minMs = Math.min(rec.minMs, elapsed);
    rec.maxMs = Math.max(rec.maxMs, elapsed);
    rec.lastMs = elapsed;
    this.records.set(opName, rec);
    return elapsed;
  }

  // 함수 래핑
  wrap<T>(name: string, fn: () => T): T {
    this.begin(name);
    try {
      return fn();
    } finally {
      this.end(name);
    }
  }

  // 전체 측정 시간
  totalTime(): number {
    let t = 0;
    for (const r of this.records.values()) t += r.totalMs;
    return t;
  }

  // 정렬된 레코드 (시간 내림차순)
  sorted(): OpRecord[] {
    return [...this.records.values()].sort((a, b) => b.totalMs - a.totalMs);
  }

  // 특정 연산 결과
  get(name: string): OpRecord | undefined {
    return this.records.get(name);
  }

  // ─── 리포트 ──────────────────────────────────────────────

  report(topN = 10): string {
    const sorted = this.sorted().slice(0, topN);
    const total = this.totalTime();
    const lines: string[] = [
      '┌─────────────────────────────────────────────────────────┐',
      '│            FreeLang v8 ML — Performance Report          │',
      '├────────────────────┬───────┬──────────┬────────┬────────┤',
      '│ Op                 │ Calls │ Total ms │ Avg ms │  %     │',
      '├────────────────────┼───────┼──────────┼────────┼────────┤',
    ];

    for (const r of sorted) {
      const pct = total > 0 ? ((r.totalMs / total) * 100).toFixed(1) : '0.0';
      const avgMs = (r.totalMs / r.calls).toFixed(3);
      lines.push(
        `│ ${r.name.padEnd(18).slice(0, 18)} │ ${String(r.calls).padStart(5)} │ ${r.totalMs.toFixed(2).padStart(8)} │ ${avgMs.padStart(6)} │ ${pct.padStart(5)}% │`
      );
    }

    lines.push('├────────────────────┴───────┴──────────┴────────┴────────┤');
    lines.push(`│ Total: ${total.toFixed(2)}ms                                       │`.slice(0, 62) + '│');
    lines.push('└─────────────────────────────────────────────────────────┘');
    return lines.join('\n');
  }

  // JSON 출력
  toJSON(): Record<string, OpRecord> {
    return Object.fromEntries(this.records);
  }

  // 리셋
  reset(): void {
    this.records.clear();
    this.stack = [];
  }
}

// ============================================================
// 벤치마크 유틸
// ============================================================

export interface BenchResult {
  name: string;
  runs: number;
  totalMs: number;
  avgMs: number;
  minMs: number;
  maxMs: number;
  opsPerSec: number;
}

export function bench(
  name: string,
  fn: () => void,
  runs = 100,
  warmup = 10
): BenchResult {
  // 웜업
  for (let i = 0; i < warmup; i++) fn();

  const times: number[] = [];
  for (let i = 0; i < runs; i++) {
    const t0 = performance.now();
    fn();
    times.push(performance.now() - t0);
  }

  const totalMs = times.reduce((a, b) => a + b, 0);
  const avgMs = totalMs / runs;
  const minMs = Math.min(...times);
  const maxMs = Math.max(...times);

  return {
    name,
    runs,
    totalMs,
    avgMs,
    minMs,
    maxMs,
    opsPerSec: 1000 / avgMs,
  };
}

export function compareBench(
  baseline: BenchResult,
  optimized: BenchResult
): string {
  const speedup = baseline.avgMs / optimized.avgMs;
  const sign = speedup >= 1 ? '🚀' : '🐢';
  return [
    `비교: ${baseline.name} vs ${optimized.name}`,
    `  기준:    ${baseline.avgMs.toFixed(3)}ms avg (${baseline.opsPerSec.toFixed(0)} ops/s)`,
    `  최적화:  ${optimized.avgMs.toFixed(3)}ms avg (${optimized.opsPerSec.toFixed(0)} ops/s)`,
    `  ${sign} 속도 향상: ${speedup.toFixed(2)}x`,
  ].join('\n');
}

// ============================================================
// 전역 프로파일러
// ============================================================

export const globalProfiler = new Profiler(false); // 기본 비활성

export function enableProfiling(): void {
  globalProfiler.enabled = true;
}

export function disableProfiling(): void {
  globalProfiler.enabled = false;
}

