  sigmoid(): Value {
    const s = 1 / (1 + Math.exp(-this.data));
    const out = new Value(s, [this]);
    out._backward = () => {
      this.grad += s * (1 - s) * out.grad;
    };
    return out;
  }

  neg(): Value {
    const out = new Value(-this.data, [this]);
    out._backward = () => { this.grad -= out.grad; };
    return out;
  }

  sub(other: Value): Value { return this.add(other.neg()); }

  exp(): Value {
    const e = Math.exp(this.data);
    const out = new Value(e, [this]);
    out._backward = () => { this.grad += e * out.grad; };
    return out;
  }

  log(): Value {
    const out = new Value(Math.log(this.data + 1e-10), [this]);
    out._backward = () => { this.grad += (1 / (this.data + 1e-10)) * out.grad; };
    return out;
  }

  static from(n: number): Value { return new Value(n); }

  // 위상 정렬 결과를 캐싱 (같은 그래프 재사용 시 속도 향상)
  static buildTopo(root: Value): Value[] {
    const topo: Value[] = [];
    const visited = new Set<Value>();
    const build = (v: Value) => {
      if (!visited.has(v)) {
        visited.add(v);
        for (const p of v._prev) build(p);
        topo.push(v);
      }
    };
    build(root);
    return topo;
  }
}

