// FreeLang v8 ML — Phase 7 성능 최적화 테스트
import {
  matmulTiled, batchMatmul,
  addInPlace, scaleInPlace, reluInPlace, sigmoidInPlace, tanhInPlace,
  dotProduct, softmax, layerNorm, embeddingLookup,
  crossEntropyLoss, AdamF32,
  CosineScheduler, StepDecayScheduler,
  transpose2D, gradClipNorm, BufferPool, globalPool,
} from '../src/ml/tensor_ops';
import { Profiler, bench, compareBench } from '../src/ml/profiler';
import { Value } from '../src/ml/autodiff';
import { Adam, AdamW, RMSProp } from '../src/ml/optimizer';
import { Lexer } from '../src/lexer/lexer';
import { Parser } from '../src/parser/parser';
import { Interpreter } from '../src/runtime/interpreter';

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
  }
}

function assert(cond: boolean, msg: string) {
  if (!cond) throw new Error(msg);
}

function assertClose(a: number, b: number, tol = 1e-4, msg = '') {
  if (Math.abs(a - b) > tol) throw new Error(`${msg} expected ${b}, got ${a} (diff=${Math.abs(a-b).toExponential(2)})`);
}

function run(src: string) {
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  if (errors.length > 0) throw new Error(`파서: ${errors[0].message}`);
  new Interpreter().run(program);
}

// ======================================================
// 1. Tiled Matmul
// ======================================================
console.log('\n[1] Tiled Matmul (캐시 친화적)');

test('matmulTiled: [2,3] @ [3,2] = [2,2]', () => {
  // A = [[1,2,3],[4,5,6]], B = [[7,8],[9,10],[11,12]]
  const A = new Float32Array([1, 2, 3, 4, 5, 6]);
  const B = new Float32Array([7, 8, 9, 10, 11, 12]);
  const C = matmulTiled(A, B, 2, 3, 2);
  // [1*7+2*9+3*11, 1*8+2*10+3*12] = [58, 64]
  assertClose(C[0], 58, 1e-3, 'C[0][0]');
  assertClose(C[1], 64, 1e-3, 'C[0][1]');
  assertClose(C[2], 139, 1e-3, 'C[1][0]');
  assertClose(C[3], 154, 1e-3, 'C[1][1]');
});

test('matmulTiled: [4,4] 정방 행렬', () => {
  const A = new Float32Array(Array.from({length: 16}, (_, i) => i + 1));
  const B = Float32Array.from(A);
  const C = matmulTiled(A, B, 4, 4, 4);
  // A @ B = A^2, A[0][0] = 1*1+2*5+3*9+4*13 = 1+10+27+52 = 90
  assertClose(C[0], 90, 1e-2, 'C[0][0]');
  assert(C.length === 16, `크기: ${C.length}`);
});

test('matmulTiled: 큰 행렬 [64,64] @ [64,64]', () => {
  const N = 64;
  const A = new Float32Array(N * N).map(() => Math.random() * 0.1);
  const B = new Float32Array(N * N).map(() => Math.random() * 0.1);
  const C = matmulTiled(A, B, N, N, N);
  assert(C.length === N * N, `크기: ${C.length}`);
  assert(!isNaN(C[0]), 'NaN 발생');
});

test('matmulTiled: [1,4] @ [4,1] = 스칼라', () => {
  const A = new Float32Array([1, 2, 3, 4]);
  const B = new Float32Array([1, 1, 1, 1]);
  const C = matmulTiled(A, B, 1, 4, 1);
