print("norm^2:", norm_sq)
  `);
  assert(true, '');
});

// ======================================================
// 결과
// ======================================================
console.log(`\n${'='.repeat(40)}`);
console.log(`결과: ${passed}/${passed + failed} PASS`);
if (failed > 0) process.exit(1);

