// FreeLang v8 ML — Phase 7 성능 최적화 테스트
import {
  matmulTiled, batchMatmul,
  addInPlace, scaleInPlace, reluInPlace, sigmoidInPlace, tanhInPlace,
  dotProduct, softmax, layerNorm, embeddingLookup,
  crossEntropyLoss, AdamF32,
  CosineScheduler, StepDecayScheduler,
  transpose2D, gradClipNorm, BufferPool, globalPool,
} from '../src/ml/tensor_ops';
import { Profiler, bench, compareBench } from '../src/ml/profiler';
import { Value } from '../src/ml/autodiff';
import { Adam, AdamW, RMSProp } from '../src/ml/optimizer';
import { Lexer } from '../src/lexer/lexer';
import { Parser } from '../src/parser/parser';
import { Interpreter } from '../src/runtime/interpreter';

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
  }
}

function assert(cond: boolean, msg: string) {
  if (!cond) throw new Error(msg);
}

function assertClose(a: number, b: number, tol = 1e-4, msg = '') {
  if (Math.abs(a - b) > tol) throw new Error(`${msg} expected ${b}, got ${a} (diff=${Math.abs(a-b).toExponential(2)})`);
}

function run(src: string) {
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  if (errors.length > 0) throw new Error(`파서: ${errors[0].message}`);
  new Interpreter().run(program);
}

// ======================================================
// 1. Tiled Matmul
// ======================================================
console.log('\n[1] Tiled Matmul (캐시 친화적)');

test('matmulTiled: [2,3] @ [3,2] = [2,2]', () => {
  // A = [[1,2,3],[4,5,6]], B = [[7,8],[9,10],[11,12]]
  const A = new Float32Array([1, 2, 3, 4, 5, 6]);
  const B = new Float32Array([7, 8, 9, 10, 11, 12]);
  const C = matmulTiled(A, B, 2, 3, 2);
  // [1*7+2*9+3*11, 1*8+2*10+3*12] = [58, 64]
  assertClose(C[0], 58, 1e-3, 'C[0][0]');
  assertClose(C[1], 64, 1e-3, 'C[0][1]');
  assertClose(C[2], 139, 1e-3, 'C[1][0]');
  assertClose(C[3], 154, 1e-3, 'C[1][1]');
});

test('matmulTiled: [4,4] 정방 행렬', () => {
  const A = new Float32Array(Array.from({length: 16}, (_, i) => i + 1));
  const B = Float32Array.from(A);
  const C = matmulTiled(A, B, 4, 4, 4);
  // A @ B = A^2, A[0][0] = 1*1+2*5+3*9+4*13 = 1+10+27+52 = 90
  assertClose(C[0], 90, 1e-2, 'C[0][0]');
  assert(C.length === 16, `크기: ${C.length}`);
});

test('matmulTiled: 큰 행렬 [64,64] @ [64,64]', () => {
  const N = 64;
  const A = new Float32Array(N * N).map(() => Math.random() * 0.1);
  const B = new Float32Array(N * N).map(() => Math.random() * 0.1);
  const C = matmulTiled(A, B, N, N, N);
  assert(C.length === N * N, `크기: ${C.length}`);
  assert(!isNaN(C[0]), 'NaN 발생');
});

test('matmulTiled: [1,4] @ [4,1] = 스칼라', () => {
  const A = new Float32Array([1, 2, 3, 4]);
  const B = new Float32Array([1, 1, 1, 1]);
  const C = matmulTiled(A, B, 1, 4, 1);
  assertClose(C[0], 10, 1e-4, 'dot product');
});

test('batchMatmul: [2,2,3] @ [2,3,2]', () => {
  const A = new Float32Array([1,2,3, 4,5,6,  1,0,0, 0,1,0]);
  const B = new Float32Array([1,0, 0,1, 1,0,  2,0, 0,2, 0,0]);
  const { data, shape } = batchMatmul(A, [2,2,3], B, [2,3,2]);
  assert(shape[0] === 2 && shape[1] === 2 && shape[2] === 2, `shape: ${shape}`);
  assert(data.length === 8, `크기: ${data.length}`);
});

// ======================================================
// 2. 원소별 연산 (루프 언롤)
// ======================================================
console.log('\n[2] 원소별 연산 (4-way 언롤)');

test('addInPlace: 덧셈', () => {
  const a = new Float32Array([1, 2, 3, 4, 5]);
  const b = new Float32Array([10, 20, 30, 40, 50]);
  addInPlace(a, b);
  assert(a[0] === 11 && a[4] === 55, `a: ${[...a]}`);
});

test('scaleInPlace: 스칼라 곱', () => {
  const a = new Float32Array([1, 2, 3, 4, 5]);
  scaleInPlace(a, 2);
  assert(a[0] === 2 && a[4] === 10, `a: ${[...a]}`);
});

test('reluInPlace: 음수 → 0', () => {
  const a = new Float32Array([-3, -1, 0, 1, 3]);
  reluInPlace(a);
  assert(a[0] === 0 && a[1] === 0 && a[2] === 0, `relu: ${[...a]}`);
  assert(a[3] === 1 && a[4] === 3, `relu pos: ${[...a]}`);
});

test('sigmoidInPlace: 범위 (0,1)', () => {
  const a = new Float32Array([-10, 0, 10]);
  sigmoidInPlace(a);
  assert(a[0] < 0.01, `sigmoid(-10): ${a[0]}`);
  assertClose(a[1], 0.5, 1e-3, 'sigmoid(0)');
  assert(a[2] > 0.99, `sigmoid(10): ${a[2]}`);
});

test('tanhInPlace: 범위 (-1,1)', () => {
  const a = new Float32Array([-10, 0, 10]);
  tanhInPlace(a);
  assert(a[0] < -0.99, `tanh(-10): ${a[0]}`);
  assertClose(a[1], 0, 1e-3, 'tanh(0)');
  assert(a[2] > 0.99, `tanh(10): ${a[2]}`);
});

test('dotProduct: 벡터 내적', () => {
  const a = new Float32Array([1, 2, 3, 4]);
  const b = new Float32Array([1, 1, 1, 1]);
  assertClose(dotProduct(a, b), 10, 1e-4, 'dot');
});

test('dotProduct: 큰 벡터 [256]', () => {
  const a = new Float32Array(256).fill(1);
  const b = new Float32Array(256).fill(2);
  assertClose(dotProduct(a, b), 512, 1e-2, 'dot 256');
});

// ======================================================
// 3. 고수준 연산
// ======================================================
console.log('\n[3] 고수준 연산 (softmax / layerNorm / crossEntropy)');

test('softmax: 합 = 1', () => {
  const logits = new Float32Array([1, 2, 3, 4]);
  const probs = softmax(logits);
  const sum = probs.reduce((a, b) => a + b, 0);
  assertClose(sum, 1.0, 1e-5, 'softmax sum');
});

test('softmax: argmax 일치', () => {
  const logits = new Float32Array([0.1, 0.2, 5.0, 0.3]);
  const probs = softmax(logits);
  const argmax = probs.indexOf(Math.max(...probs));
  assert(argmax === 2, `argmax: ${argmax}`);
});

test('softmax: 수치 안정 (큰 값)', () => {
  const logits = new Float32Array([1000, 1001, 999]);
  const probs = softmax(logits);
  const sum = probs.reduce((a, b) => a + b, 0);
  assertClose(sum, 1.0, 1e-5, 'large softmax sum');
  assert(!isNaN(probs[0]), 'NaN 발생');
});

test('layerNorm: 출력 평균 ≈ 0', () => {
  const x = new Float32Array([1, 2, 3, 4]);
  const gamma = new Float32Array([1, 1, 1, 1]);
  const beta = new Float32Array([0, 0, 0, 0]);
  const out = layerNorm(x, gamma, beta, 4);
  const mean = out.reduce((a, b) => a + b, 0) / 4;
  assertClose(mean, 0, 1e-4, 'layerNorm mean');
});

test('layerNorm: 출력 분산 ≈ 1', () => {
  const x = new Float32Array([1, 2, 3, 4]);
  const gamma = new Float32Array([1, 1, 1, 1]);
  const beta = new Float32Array([0, 0, 0, 0]);
  const out = layerNorm(x, gamma, beta, 4);
  const mean = out.reduce((a, b) => a + b, 0) / 4;
  const variance = out.reduce((s, v) => s + (v - mean) ** 2, 0) / 4;
  assertClose(variance, 1.0, 0.01, 'layerNorm variance');
});

test('layerNorm: gamma/beta 적용', () => {
  const x = new Float32Array([1, 2, 3, 4]);
  const gamma = new Float32Array([2, 2, 2, 2]);
  const beta = new Float32Array([1, 1, 1, 1]);
  const out = layerNorm(x, gamma, beta, 4);
  // gamma=2, beta=1 → 범위가 기본보다 커야 함
  assert(out[3] > out[0], `범위: ${out[0]} ~ ${out[3]}`);
});

test('embeddingLookup: id → 벡터', () => {
  // table [4, 3]: 4개 토큰, dim=3
  const table = new Float32Array([
    1, 0, 0,  // id=0
    0, 1, 0,  // id=1
    0, 0, 1,  // id=2
    1, 1, 1,  // id=3
  ]);
  const out = embeddingLookup([0, 2, 3], table, 3);
  assert(out.length === 9, `길이: ${out.length}`);
  assertClose(out[0], 1, 1e-5, 'emb[0][0]');  // id=0, dim=0
  assertClose(out[5], 1, 1e-5, 'emb[1][2]');  // id=2, dim=2
  assertClose(out[8], 1, 1e-5, 'emb[2][2]');  // id=3, dim=2
});

test('crossEntropyLoss: 완벽한 예측 → loss 낮음', () => {
  // seq=1, vocab=4, target=2
  const logits = new Float32Array([0.0, 0.0, 10.0, 0.0]);
  const { loss } = crossEntropyLoss(logits, [2], 4);
  assert(loss < 0.01, `loss: ${loss}`);
});

test('crossEntropyLoss: grad shape', () => {
  const logits = new Float32Array([1, 2, 3, 4,  1, 2, 3, 4]);
  const { loss, grad } = crossEntropyLoss(logits, [0, 3], 4);
  assert(grad.length === 8, `grad 크기: ${grad.length}`);
  assert(!isNaN(loss), `loss NaN`);
});

test('transpose2D: [2,3] → [3,2]', () => {
  const A = new Float32Array([1, 2, 3, 4, 5, 6]);
  const At = transpose2D(A, 2, 3);
  assertClose(At[0], 1, 1e-5, 'At[0]');
  assertClose(At[1], 4, 1e-5, 'At[1]');
  assertClose(At[2], 2, 1e-5, 'At[2]');
});

// ======================================================
// 4. AdamF32 옵티마이저
// ======================================================
console.log('\n[4] AdamF32 (Float32Array 기반 — GC 없음)');

test('AdamF32: 파라미터 업데이트', () => {
  const params = new Float32Array([1.0, 2.0, 3.0]);
  const grads = new Float32Array([0.1, 0.2, 0.3]);
  const optim = new AdamF32(3, 0.01);
  const before = params[0];
  optim.step(params, grads);
  assert(params[0] !== before, '파라미터 변경 없음');
});

test('AdamF32: gradient → 0이면 업데이트 없음', () => {
  const params = new Float32Array([1.0, 2.0]);
  const grads = new Float32Array([0, 0]);
  const optim = new AdamF32(2, 0.01);
  optim.step(params, grads);
  // grad=0이면 m=0, v=0 → mHat/sqrt(vHat) ≈ 0
  assertClose(params[0], 1.0, 0.001, 'grad=0 파라미터');
});

test('AdamF32: zeroGrad', () => {
  const grads = new Float32Array([1, 2, 3]);
  const optim = new AdamF32(3);
  optim.zeroGrad(grads);
  assert(grads.every(v => v === 0), `grads: ${[...grads]}`);
});

test('AdamF32: weight decay', () => {
  const params = new Float32Array([1.0]);
  const grads = new Float32Array([0.0]);
  const optim = new AdamF32(1, 0.01, 0.9, 0.999, 1e-8, 0.1);
  for (let i = 0; i < 10; i++) optim.step(params, grads);
  // weight decay로 인해 파라미터 감소
  assert(params[0] < 1.0, `params[0]: ${params[0]}`);
});

test('AdamF32: loss 감소 시뮬레이션', () => {
  // y = Wx 회귀, 단순 1D
  const W = new Float32Array([2.0]);  // 목표: 1.0
  const grads = new Float32Array(1);
  const optim = new AdamF32(1, 0.1);

  let prevLoss = Infinity;
  let decreased = false;
  for (let i = 0; i < 50; i++) {
    // loss = (W - 1)^2, dL/dW = 2*(W - 1)
    const loss = (W[0] - 1) ** 2;
    grads[0] = 2 * (W[0] - 1);
    optim.step(W, grads);
    if (loss < prevLoss) decreased = true;
    prevLoss = loss;
  }
  assert(decreased, 'loss 감소 없음');
  assert(Math.abs(W[0] - 1.0) < 0.1, `W 수렴 실패: ${W[0]}`);
});

test('AdamF32: reset', () => {
  const params = new Float32Array([1.0]);
  const grads = new Float32Array([0.5]);
  const optim = new AdamF32(1, 0.01);
  optim.step(params, grads);
  optim.reset();
  const params2 = new Float32Array([1.0]);
  const grads2 = new Float32Array([0.5]);
  const p1 = params[0];
  optim.step(params2, grads2);
  // reset 후 첫 step 결과는 처음 step과 같아야 함
  assertClose(params[0] - 1.0, params2[0] - 1.0, 1e-5, 'reset 후 동일');
});

// ======================================================
// 5. LR 스케줄러
// ======================================================
console.log('\n[5] LR 스케줄러');

test('CosineScheduler: step=0 → baseLR', () => {
  const sched = new CosineScheduler(0.01, 0.0001, 100);
  assertClose(sched.getLR(0), 0.01, 1e-6, 'step=0 LR');
});

test('CosineScheduler: step=totalSteps → minLR', () => {
  const sched = new CosineScheduler(0.01, 0.0001, 100);
  assertClose(sched.getLR(100), 0.0001, 1e-5, 'step=100 LR');
});

test('CosineScheduler: 단조 감소', () => {
  const sched = new CosineScheduler(0.01, 0.0001, 100);
  let prev = sched.getLR(0);
  let monotone = true;
  for (let s = 1; s <= 100; s++) {
    const lr = sched.getLR(s);
    if (lr > prev + 1e-9) monotone = false;
    prev = lr;
  }
  assert(monotone, '단조 감소 아님');
});

test('CosineScheduler: warmup', () => {
  const sched = new CosineScheduler(0.01, 0.0001, 100, 10);
  const lr5 = sched.getLR(5);
  const lr10 = sched.getLR(10);
  assert(lr5 < lr10, `warmup 5=${lr5} < 10=${lr10}`);
  assertClose(lr10, 0.01, 1e-5, 'warmup 끝');
});

test('StepDecayScheduler: 스텝마다 감소', () => {
  const sched = new StepDecayScheduler(0.1, 10, 0.5);
  assertClose(sched.getLR(0), 0.1, 1e-6, 'step=0');
  assertClose(sched.getLR(10), 0.05, 1e-6, 'step=10');
  assertClose(sched.getLR(20), 0.025, 1e-6, 'step=20');
});

test('AdamW: weight decay 독립 적용', () => {
  const p = Value.from(1.0);
  const optim = new AdamW(0.01, 0.9, 0.999, 1e-8, 0.1);
  p.grad = 0;
  for (let i = 0; i < 5; i++) optim.step([p]);
  assert(p.data < 1.0, `AdamW decay: ${p.data}`);
});

test('AdamW: 스케줄러 연동', () => {
  const p = Value.from(1.0);
  const sched = new CosineScheduler(0.1, 0.001, 100);
  const optim = new AdamW(0.1).setScheduler(sched);
  p.grad = 0.1;
  optim.step([p]);
  assert(p.data !== 1.0, 'AdamW 업데이트 없음');
  const lr = optim.currentLR();
  assert(lr > 0, `LR: ${lr}`);
});

test('RMSProp: 파라미터 업데이트', () => {
  const p = Value.from(2.0);
  p.grad = 0.5;
  const optim = new RMSProp(0.01);
  optim.step([p]);
  assert(p.data < 2.0, `RMSProp: ${p.data}`);
});

// ======================================================
// 6. gradClipNorm
// ======================================================
console.log('\n[6] gradClipNorm');

test('gradClipNorm: 클리핑 적용', () => {
  const grads = new Float32Array([3, 4]);  // norm=5
  const norm = gradClipNorm(grads, 1.0);
  // 클리핑 후 norm ≈ 1.0
  const newNorm = Math.sqrt(grads[0]**2 + grads[1]**2);
  assertClose(newNorm, 1.0, 1e-4, 'clipped norm');
  assert(norm > 0, `반환 norm: ${norm}`);
});

test('gradClipNorm: 작은 norm → 변경 없음', () => {
  const grads = new Float32Array([0.1, 0.1]);
  const orig0 = grads[0];
  gradClipNorm(grads, 5.0);
  assertClose(grads[0], orig0, 1e-6, '변경 없어야 함');
});

// ======================================================
// 7. BufferPool
// ======================================================
console.log('\n[7] BufferPool (메모리 재사용)');

test('BufferPool: acquire → release → 재사용', () => {
  const pool = new BufferPool();
  const buf1 = pool.acquire(16);
  pool.release(buf1);
  const buf2 = pool.acquire(16);
  assert(buf2 === buf1, '버퍼 재사용 실패');
});

test('BufferPool: 다른 크기 분리', () => {
  const pool = new BufferPool();
  const a = pool.acquire(8);
  const b = pool.acquire(16);
  pool.release(a);
  pool.release(b);
  const a2 = pool.acquire(8);
  assert(a2 === a, '크기 8 재사용 실패');
});

test('BufferPool: stats 추적', () => {
  const pool = new BufferPool();
  pool.acquire(4);
  const b = pool.acquire(4);
  pool.release(b);
  pool.acquire(4); // 재사용
  const s = pool.stats();
  assert(s.allocated >= 2, `allocated: ${s.allocated}`);
  assert(s.reused >= 1, `reused: ${s.reused}`);
});

// ======================================================
// 8. Profiler
// ======================================================
console.log('\n[8] Profiler (성능 측정)');

test('Profiler: begin/end 측정', () => {
  const prof = new Profiler();
  prof.begin('matmul');
  // 간단한 작업
  let s = 0;
  for (let i = 0; i < 1000; i++) s += i;
  const elapsed = prof.end('matmul');
  assert(elapsed >= 0, `elapsed: ${elapsed}`);
  const rec = prof.get('matmul');
  assert(rec !== undefined, 'record 없음');
  assert(rec!.calls === 1, `calls: ${rec!.calls}`);
});

test('Profiler: wrap 편의 함수', () => {
  const prof = new Profiler();
  const result = prof.wrap('test_op', () => 42);
  assert(result === 42, `wrap 반환값: ${result}`);
  assert(prof.get('test_op')?.calls === 1, 'wrap 기록 없음');
});

test('Profiler: 누적 통계', () => {
  const prof = new Profiler();
  for (let i = 0; i < 5; i++) {
    prof.begin('loop');
    prof.end('loop');
  }
  const rec = prof.get('loop')!;
  assert(rec.calls === 5, `calls: ${rec.calls}`);
  assert(rec.totalMs >= 0, `totalMs: ${rec.totalMs}`);
});

test('Profiler: sorted 반환 순서', () => {
  const prof = new Profiler();
  prof.begin('fast'); prof.end('fast');
  prof.begin('slow');
  let s = 0; for (let i = 0; i < 1e6; i++) s += i;
  prof.end('slow');
  const sorted = prof.sorted();
  assert(sorted.length === 2, `sorted 길이: ${sorted.length}`);
  // totalMs 내림차순
  assert(sorted[0].totalMs >= sorted[1].totalMs, '정렬 오류');
});

test('Profiler: report 문자열 생성', () => {
  const prof = new Profiler();
  prof.begin('op1'); prof.end('op1');
  const report = prof.report();
  assert(report.includes('op1'), 'op1 없음');
  assert(report.includes('Calls'), 'Calls 헤더 없음');
});

test('Profiler: 비활성화 시 오버헤드 없음', () => {
  const prof = new Profiler(false);
  prof.begin('noop');
  prof.end('noop');
  assert(prof.get('noop') === undefined, '비활성화 기록됨');
});

test('Profiler: reset 후 초기화', () => {
  const prof = new Profiler();
  prof.begin('x'); prof.end('x');
  prof.reset();
  assert(prof.get('x') === undefined, 'reset 후 남아있음');
  assert(prof.sorted().length === 0, '레코드 남아있음');
});

// ======================================================
// 9. bench 유틸
// ======================================================
console.log('\n[9] bench 유틸');

test('bench: 결과 구조', () => {
  const result = bench('noop', () => {}, 10, 2);
  assert(result.name === 'noop', `name: ${result.name}`);
  assert(result.runs === 10, `runs: ${result.runs}`);
  assert(result.avgMs >= 0, `avgMs: ${result.avgMs}`);
  assert(result.minMs <= result.maxMs, `min/max 역전`);
  assert(result.opsPerSec > 0, `opsPerSec: ${result.opsPerSec}`);
});

test('bench: matmul 32x32 시간 측정', () => {
  const A = new Float32Array(32 * 32).fill(0.1);
  const B = new Float32Array(32 * 32).fill(0.1);
  const result = bench('matmul_32', () => matmulTiled(A, B, 32, 32, 32), 20, 5);
  assert(result.avgMs >= 0, `avgMs: ${result.avgMs}`);
  console.log(`    matmul 32x32: ${result.avgMs.toFixed(3)}ms avg, ${result.opsPerSec.toFixed(0)} ops/s`);
});

test('compareBench: 비교 문자열 생성', () => {
  const baseline = bench('baseline', () => {
    const a = new Float32Array(64); let s = 0;
    for (let i = 0; i < 64; i++) s += a[i];
  }, 10);
  const optimized = bench('optimized', () => {
    dotProduct(new Float32Array(64), new Float32Array(64));
  }, 10);
  const cmp = compareBench(baseline, optimized);
  assert(cmp.includes('baseline'), 'baseline 없음');
  assert(cmp.includes('속도 향상'), '속도 향상 없음');
});

// ======================================================
// 10. Value 확장 (sigmoid, neg, sub, exp, log)
// ======================================================
console.log('\n[10] Value 확장 연산');

test('Value.sigmoid: 범위 (0,1)', () => {
  const v = Value.from(0);
  const s = v.sigmoid();
  assertClose(s.data, 0.5, 1e-4, 'sigmoid(0)');
});

test('Value.sigmoid: 역전파', () => {
  const v = Value.from(0);
  const s = v.sigmoid();
  s.backward();
  // dL/dv = s*(1-s) = 0.5*0.5 = 0.25
  assertClose(v.grad, 0.25, 1e-4, 'sigmoid grad');
});

test('Value.neg: 부호 반전', () => {
  const v = Value.from(3);
  const n = v.neg();
  assertClose(n.data, -3, 1e-6, 'neg');
  n.backward();
  assertClose(v.grad, -1, 1e-6, 'neg grad');
});

test('Value.sub: 뺄셈', () => {
  const a = Value.from(5);
  const b = Value.from(3);
  const c = a.sub(b);
  assertClose(c.data, 2, 1e-6, 'sub');
});

test('Value.exp: 지수함수', () => {
  const v = Value.from(1);
  const e = v.exp();
  assertClose(e.data, Math.E, 1e-4, 'exp(1)');
  e.backward();
  assertClose(v.grad, Math.E, 1e-4, 'exp grad');
});

test('Value.log: 자연로그', () => {
  const v = Value.from(Math.E);
  const l = v.log();
  assertClose(l.data, 1.0, 1e-4, 'log(e)');
});

test('Value.buildTopo: 캐시 기반 위상 정렬', () => {
  const a = Value.from(2);
  const b = Value.from(3);
  const c = a.mul(b);
  const d = c.add(a);
  const topo = Value.buildTopo(d);
  assert(topo.length >= 3, `topo 크기: ${topo.length}`);
  assert(topo[topo.length - 1] === d, '루트가 마지막이어야 함');
});

