  `);
  assert(true, '');
});

test('cosine schedule 수동 .fl8', () => {
  run(`
let base_lr = 0.01
let min_lr = 0.0001
let step = 50
let total = 100
let progress = step / total
let scale = 0.5
let lr = min_lr + (base_lr - min_lr) * scale
print("lr:", lr)
  `);
  assert(true, '');
});

test('gradient clipping .fl8', () => {
  run(`
let grads = [3.0, 4.0]
let norm_sq = grads[0] * grads[0] + grads[1] * grads[1]
print("norm^2:", norm_sq)
  `);
  assert(true, '');
});

