// FreeLang v8 ML — 타입 오류 (Phase 8)

export type TypeErrorKind =
  | 'type_mismatch'
  | 'undefined_variable'
  | 'undefined_function'
  | 'wrong_arity'
  | 'not_callable'
  | 'not_indexable'
  | 'no_field'
  | 'return_mismatch'
  | 'tensor_shape_mismatch'
  | 'infinite_type'
  | 'generic_arity';

export class TypeErrorReport {
  readonly kind: TypeErrorKind;
  readonly message: string;
  readonly line: number;
  readonly col: number;
  readonly hint?: string;

  constructor(kind: TypeErrorKind, message: string, line: number, col: number, hint?: string) {
    this.kind = kind;
    this.message = message;
    this.line = line;
    this.col = col;
    this.hint = hint;
  }

  toString(): string {
    const loc = `${this.line}:${this.col}`;
    const h = this.hint ? `\n  힌트: ${this.hint}` : '';
    return `[타입 오류] ${loc}: ${this.message}${h}`;
  }
}

export class TypeError extends Error {
  readonly report: TypeErrorReport;
  constructor(report: TypeErrorReport) {
    super(report.message);
    this.report = report;
  }
}

// 헬퍼
export function typeMismatch(
  expected: string, got: string,
  line: number, col: number, hint?: string
): TypeErrorReport {
  return new TypeErrorReport(
    'type_mismatch',
    `타입 불일치: ${expected} 기대, ${got} 받음`,
    line, col, hint
  );
}

export function undefinedVar(name: string, line: number, col: number): TypeErrorReport {
  return new TypeErrorReport(
    'undefined_variable', `정의되지 않은 변수: '${name}'`, line, col,
    `'let ${name} = ...'로 선언하셨나요?`
  );
}

export function wrongArity(
  name: string, expected: number, got: number,
  line: number, col: number
): TypeErrorReport {
  return new TypeErrorReport(
    'wrong_arity',
    `함수 '${name}': ${expected}개 인수 필요, ${got}개 전달`,
    line, col
  );
}

export function noField(typeName: string, field: string, line: number, col: number): TypeErrorReport {
  return new TypeErrorReport(
    'no_field', `타입 '${typeName}'에 필드 '${field}' 없음`, line, col
  );
}

export function tensorShapeMismatch(
  op: string, a: string, b: string,
  line: number, col: number
): TypeErrorReport {
  return new TypeErrorReport(
    'tensor_shape_mismatch',
    `${op}: Tensor shape 불일치 ${a} vs ${b}`,
    line, col
  );
}

