// ============================================================
// FL8 타입 표현 (내부용 — TypeAnnotation과 별개)
// ============================================================

export type FL8Type =
  | { tag: 'number' }
  | { tag: 'bool' }
  | { tag: 'string' }
  | { tag: 'null' }
  | { tag: 'void' }
  | { tag: 'tensor'; shape: (number | '?')[]; dtype: 'f32' | 'f64' | 'i32' }
  | { tag: 'array'; elem: FL8Type }
  | { tag: 'fn'; params: FL8Type[]; ret: FL8Type; name?: string }
  | { tag: 'struct'; name: string; fields: Record<string, FL8Type> }
  // ML 특수 타입
  | { tag: 'mlp' }
  | { tag: 'adam' }
  | { tag: 'adamw' }
  | { tag: 'tokenizer'; kind: 'char' | 'bpe' }
  | { tag: 'gpt' }
  | { tag: 'module' }
  | { tag: 'trainer' }
  | { tag: 'dataloader' }
  // 타입 변수 (HM 추론용)
  | { tag: 'var'; id: number }
  // 알 수 없는 타입 (에러 복구용)
  | { tag: 'unknown' };

// 편의 생성자
export const T = {
  num:     (): FL8Type => ({ tag: 'number' }),
  bool:    (): FL8Type => ({ tag: 'bool' }),
  str:     (): FL8Type => ({ tag: 'string' }),
  null_:   (): FL8Type => ({ tag: 'null' }),
  void_:   (): FL8Type => ({ tag: 'void' }),
  unknown: (): FL8Type => ({ tag: 'unknown' }),
  array:   (elem: FL8Type): FL8Type => ({ tag: 'array', elem }),
  fn:      (params: FL8Type[], ret: FL8Type, name?: string): FL8Type => ({ tag: 'fn', params, ret, name }),
  tensor:  (shape: (number | '?')[], dtype: 'f32' | 'f64' | 'i32' = 'f32'): FL8Type => ({ tag: 'tensor', shape, dtype }),
  var_:    (id: number): FL8Type => ({ tag: 'var', id }),
  struct:  (name: string, fields: Record<string, FL8Type>): FL8Type => ({ tag: 'struct', name, fields }),
};

// ============================================================
// 타입을 문자열로
// ============================================================

export function typeToString(t: FL8Type): string {
  switch (t.tag) {
    case 'number':    return 'number';
    case 'bool':      return 'bool';
    case 'string':    return 'string';
    case 'null':      return 'null';
    case 'void':      return 'void';
    case 'unknown':   return 'unknown';
    case 'var':       return `'T${t.id}`;
    case 'array':     return `Array<${typeToString(t.elem)}>`;
    case 'tensor':    return `Tensor[${t.shape.join(',')}]<${t.dtype}>`;
    case 'fn': {
      const ps = t.params.map(typeToString).join(', ');
      return `(${ps}) -> ${typeToString(t.ret)}`;
    }
    case 'struct':    return t.name;
    case 'mlp':       return 'MLP';
    case 'adam':      return 'Adam';
    case 'adamw':     return 'AdamW';
    case 'tokenizer': return `${t.kind === 'char' ? 'Char' : 'BPE'}Tokenizer`;
    case 'gpt':       return 'MiniGPT';
    case 'module':    return 'Module';
    case 'trainer':   return 'Trainer';
    case 'dataloader':return 'DataLoader';
