}

// ============================================================
// 타입 동등성 (unification 없이 구조적)
// ============================================================

export function typeEqual(a: FL8Type, b: FL8Type): boolean {
  if (a.tag !== b.tag) return false;
  switch (a.tag) {
    case 'array': return typeEqual(a.elem, (b as any).elem);
    case 'tensor': {
      const bt = b as typeof a;
      if (a.dtype !== bt.dtype) return false;
      if (a.shape.length !== bt.shape.length) return false;
      return a.shape.every((s, i) => s === '?' || bt.shape[i] === '?' || s === bt.shape[i]);
    }
    case 'fn': {
      const bf = b as typeof a;
      if (a.params.length !== bf.params.length) return false;
      return a.params.every((p, i) => typeEqual(p, bf.params[i])) && typeEqual(a.ret, bf.ret);
    }
    case 'struct': return (a as any).name === (b as any).name;
    case 'var':    return (a as any).id === (b as any).id;
    default:       return true;
  }
}

// ============================================================
// TypeEnv — 스코프 체인
// ============================================================

export class TypeEnv {
  private bindings = new Map<string, FL8Type>();
  private parent?: TypeEnv;

  constructor(parent?: TypeEnv) {
    this.parent = parent;
  }

  lookup(name: string): FL8Type | undefined {
    return this.bindings.get(name) ?? this.parent?.lookup(name);
  }

  define(name: string, type: FL8Type): void {
    this.bindings.set(name, type);
  }

  assign(name: string, type: FL8Type): boolean {
    if (this.bindings.has(name)) {
      this.bindings.set(name, type);
      return true;
    }
    return this.parent?.assign(name, type) ?? false;
  }

  child(): TypeEnv {
    return new TypeEnv(this);
  }

  // 현재 스코프 바인딩만 (디버그용)
  own(): Record<string, string> {
    const out: Record<string, string> = {};
    for (const [k, v] of this.bindings) out[k] = typeToString(v);
