  env.define('pop',    T.fn([arrAny], T.unknown()));
  env.define('range',  T.fn([T.num(), T.num()], T.array(T.num())));
  env.define('map',    T.fn([arrAny, T.fn([T.unknown()], T.unknown())], T.array(T.unknown())));
  env.define('filter', T.fn([arrAny, T.fn([T.unknown()], T.bool())], T.array(T.unknown())));
  env.define('reduce', T.fn([arrAny, T.fn([T.unknown(), T.unknown()], T.unknown()), T.unknown()], T.unknown()));

  // 텐서 함수
  env.define('zeros',     T.fn([T.num(), T.num()], T.tensor(['?', '?'])));
  env.define('ones',      T.fn([T.num(), T.num()], T.tensor(['?', '?'])));
  env.define('randn',     T.fn([T.num(), T.num()], T.tensor(['?', '?'])));
  env.define('matmul',    T.fn([T.tensor(['?','?']), T.tensor(['?','?'])], T.tensor(['?','?'])));
  env.define('transpose', T.fn([T.tensor(['?','?'])], T.tensor(['?','?'])));
  env.define('shape',     T.fn([T.unknown()], T.array(T.num())));

  // 손실 함수
  const tensorOrArr = T.unknown();
  env.define('mse',           T.fn([tensorOrArr, tensorOrArr], T.num()));
  env.define('mae',           T.fn([tensorOrArr, tensorOrArr], T.num()));
  env.define('cross_entropy', T.fn([tensorOrArr, tensorOrArr], T.num()));
