  // 위치 인코딩
  env.define('positional_encoding', T.fn([T.num(), T.num()], T.array(T.array(T.num()))));

  // ML 객체 생성자
  env.define('MLP',  T.fn([T.array(T.num())], { tag: 'mlp' }));
