// FreeLang v8 ML — 타입 체커 (Phase 8)
// HM-light: 타입 추론 + 단일화(unification) + 에러 수집

import { Program, Stmt, Expr, TypeAnnotation } from '../ast/ast';
import {
  FL8Type, TypeEnv, T, typeToString, typeEqual, makeBuiltinEnv, ML_FIELD_TYPES,
} from './type_env';
import {
  TypeErrorReport, typeMismatch, undefinedVar, wrongArity, noField,
} from './type_error';

// ============================================================
// 타입 변수 & 단일화 (Unification)
// ============================================================

let _varCounter = 0;

function freshVar(): FL8Type { return T.var_(_varCounter++); }

class Substitution {
  private map = new Map<number, FL8Type>();

  set(id: number, t: FL8Type): void { this.map.set(id, t); }

  apply(t: FL8Type): FL8Type {
    if (t.tag === 'var') {
      const bound = this.map.get(t.id);
      return bound ? this.apply(bound) : t;
    }
    if (t.tag === 'array') return { ...t, elem: this.apply(t.elem) };
    if (t.tag === 'fn')    return { ...t, params: t.params.map(p => this.apply(p)), ret: this.apply(t.ret) };
    return t;
  }

  // 단일화: a ≡ b를 만족하는 대입 찾기
  unify(a: FL8Type, b: FL8Type): boolean {
    a = this.apply(a);
    b = this.apply(b);

    if (a.tag === 'unknown' || b.tag === 'unknown') return true;

    if (a.tag === 'var') {
      if (b.tag === 'var' && a.id === b.id) return true;
      if (this.occursIn(a.id, b)) return false; // 무한 타입
      this.set(a.id, b);
      return true;
    }
    if (b.tag === 'var') return this.unify(b, a);

    if (a.tag !== b.tag) return false;

    if (a.tag === 'array' && b.tag === 'array')
      return this.unify(a.elem, b.elem);

    if (a.tag === 'fn' && b.tag === 'fn') {
      if (a.params.length !== b.params.length) return false;
      return a.params.every((p, i) => this.unify(p, (b as typeof a).params[i]))
          && this.unify(a.ret, (b as typeof a).ret);
    }

    return typeEqual(a, b);
  }

  private occursIn(id: number, t: FL8Type): boolean {
    t = this.apply(t);
    if (t.tag === 'var') return t.id === id;
    if (t.tag === 'array') return this.occursIn(id, t.elem);
    if (t.tag === 'fn') return t.params.some(p => this.occursIn(id, p)) || this.occursIn(id, t.ret);
    return false;
  }
}

// ============================================================
// TypeAnnotation → FL8Type 변환
// ============================================================

function annotToType(ann: TypeAnnotation): FL8Type {
  switch (ann.kind) {
    case 'i32': case 'i64': case 'f64': case 'f32': return T.num();
    case 'bool':    return T.bool();
    case 'string':  return T.str();
    case 'void':    return T.void_();
    case 'array':   return T.array(annotToType(ann.element));
    case 'tensor':  return T.tensor(ann.shape, ann.dtype);
    case 'fn':      return T.fn(ann.params.map(annotToType), annotToType(ann.returnType));
    case 'struct_ref': return { tag: 'struct', name: ann.name, fields: {} };
    case 'type_param': return T.unknown();
    case 'generic_ref': return T.unknown();
    default:        return T.unknown();
  }
}

// ============================================================
// TypeChecker
// ============================================================

export class TypeChecker {
  readonly errors: TypeErrorReport[] = [];
  private sub = new Substitution();
  private returnType: FL8Type | null = null; // 현재 함수 반환 타입

  check(program: Program): TypeEnv {
    _varCounter = 0;
    const env = makeBuiltinEnv();
    for (const stmt of program.stmts) {
      this.checkStmt(stmt, env);
    }
    return env;
  }

  // ─── 문 타입 체크 ──────────────────────────────────────────

  private checkStmt(stmt: Stmt, env: TypeEnv): void {
    switch (stmt.kind) {

      case 'var_decl': {
        const initType = this.checkExpr(stmt.init, env);
        const declType = stmt.type ? annotToType(stmt.type) : initType;
        if (stmt.type) {
          if (!this.sub.unify(initType, declType)) {
            this.errors.push(typeMismatch(
              typeToString(declType), typeToString(initType),
              stmt.line, stmt.col
            ));
          }
        }
        env.define(stmt.name, this.sub.apply(declType));
        break;
      }

      case 'fn_decl': {
        const paramTypes = stmt.params.map(p => annotToType(p.type));
        const retType = annotToType(stmt.returnType);

        const fnType = T.fn(paramTypes, retType, stmt.name);
        env.define(stmt.name, fnType);

        const inner = env.child();
        stmt.params.forEach((p, i) => inner.define(p.name, paramTypes[i]));

        const prevRet = this.returnType;
        this.returnType = retType;
        for (const s of stmt.body) this.checkStmt(s, inner);
        this.returnType = prevRet;
        break;
      }

      case 'struct_decl': {
        const fields: Record<string, FL8Type> = {};
        for (const f of stmt.fields) fields[f.name] = annotToType(f.type);
        env.define(stmt.name, T.struct(stmt.name, fields));
        break;
      }

      case 'if_stmt': {
        const condType = this.checkExpr(stmt.condition, env);
        if (!this.sub.unify(condType, T.bool()) && condType.tag !== 'unknown' && condType.tag !== 'number') {
          this.errors.push(typeMismatch('bool', typeToString(condType), stmt.line, stmt.col));
        }
        const thenEnv = env.child();
        for (const s of stmt.then) this.checkStmt(s, thenEnv);
        if (stmt.else_) {
          const elseEnv = env.child();
          for (const s of stmt.else_) this.checkStmt(s, elseEnv);
        }
        break;
      }

      case 'while_stmt': {
        this.checkExpr(stmt.condition, env);
        const inner = env.child();
        for (const s of stmt.body) this.checkStmt(s, inner);
        break;
      }

      case 'for_stmt': {
        const iterType = this.checkExpr(stmt.iterable, env);
        const inner = env.child();
        const elemType = iterType.tag === 'array' ? iterType.elem : T.unknown();
        inner.define(stmt.variable, elemType);
        for (const s of stmt.body) this.checkStmt(s, inner);
        break;
      }

      case 'for_of_stmt': {
        const iterType = this.checkExpr(stmt.iterable, env);
        const inner = env.child();
        const elemType = iterType.tag === 'array' ? iterType.elem : T.unknown();
        inner.define(stmt.variable, elemType);
        for (const s of stmt.body) this.checkStmt(s, inner);
        break;
      }

      case 'return_stmt': {
        if (stmt.value) {
          const valType = this.checkExpr(stmt.value, env);
          if (this.returnType && !this.sub.unify(valType, this.returnType)) {
            this.errors.push(typeMismatch(
              typeToString(this.returnType), typeToString(valType),
              stmt.line, stmt.col,
              '함수 반환 타입을 확인하세요'
            ));
          }
        }
        break;
      }

      case 'expr_stmt': {
        this.checkExpr(stmt.expr, env);
        break;
      }

      case 'match_stmt': {
        this.checkExpr(stmt.subject, env);
        break;
      }

      default: break;
    }
  }

  // ─── 식 타입 추론 ──────────────────────────────────────────

  checkExpr(expr: Expr, env: TypeEnv): FL8Type {
    const t = this._inferExpr(expr, env);
    return this.sub.apply(t);
  }

  private _inferExpr(expr: Expr, env: TypeEnv): FL8Type {
    switch (expr.kind) {

      case 'int_lit':    return T.num();
      case 'float_lit':  return T.num();
      case 'bool_lit':   return T.bool();
      case 'string_lit': return T.str();

      case 'ident': {
        const t = env.lookup(expr.name);
        if (!t) {
          this.errors.push(undefinedVar(expr.name, expr.line, expr.col));
          return T.unknown();
        }
        return t;
      }

      case 'binary': {
        const lt = this.checkExpr(expr.left, env);
        const rt = this.checkExpr(expr.right, env);
        const op = expr.op;

        if (['+', '-', '*', '/', '%', '**'].includes(op)) {
          // 문자열 + 허용
          if (op === '+' && (lt.tag === 'string' || rt.tag === 'string')) return T.str();
          // unknown 허용 (동적 타입)
          if (lt.tag !== 'unknown' && rt.tag !== 'unknown') {
            if (!this.sub.unify(lt, T.num())) {
              this.errors.push(typeMismatch('number', typeToString(lt), expr.line, expr.col));
            }
          }
          return T.num();
        }

        if (['<', '>', '<=', '>='].includes(op)) return T.bool();
        if (['==', '!='].includes(op)) return T.bool();
        if (['&&', '||'].includes(op)) return T.bool();

        return T.unknown();
      }

      case 'unary': {
        const t = this.checkExpr(expr.operand, env);
        if (expr.op === '!') return T.bool();
        if (expr.op === '-') return T.num();
        return t;
      }

      case 'call': {
        const calleeType = this.checkExpr(expr.callee, env);
        const argTypes = expr.args.map(a => this.checkExpr(a, env));

        if (calleeType.tag === 'unknown') return T.unknown();

        if (calleeType.tag !== 'fn') {
          this.errors.push(new (require('./type_error').TypeErrorReport)(
            'not_callable',
            `'${typeToString(calleeType)}' 타입은 호출 불가`,
            expr.line, expr.col
          ));
          return T.unknown();
        }

        // 인수 수 체크 (unknown 파라미터 허용)
        if (calleeType.params.length > 0 && calleeType.params[calleeType.params.length - 1].tag !== 'unknown') {
          if (calleeType.params.length !== argTypes.length) {
            const name = calleeType.name ?? '(anonymous)';
            this.errors.push(wrongArity(name, calleeType.params.length, argTypes.length, expr.line, expr.col));
          }
        }

        // 파라미터 타입 단일화
        const minLen = Math.min(calleeType.params.length, argTypes.length);
        for (let i = 0; i < minLen; i++) {
          if (!this.sub.unify(calleeType.params[i], argTypes[i])) {
            this.errors.push(typeMismatch(
              typeToString(calleeType.params[i]),
              typeToString(argTypes[i]),
              expr.line, expr.col,
              `${i + 1}번째 인수 타입`
            ));
          }
        }

        return this.sub.apply(calleeType.ret);
      }

      case 'index': {
        const objType = this.checkExpr(expr.object, env);
        this.checkExpr(expr.index, env);
        if (objType.tag === 'array') return objType.elem;
        if (objType.tag === 'tensor') return T.num();
        if (objType.tag === 'string') return T.str();
        if (objType.tag === 'unknown') return T.unknown();
        this.errors.push(new (require('./type_error').TypeErrorReport)(
          'not_indexable', `'${typeToString(objType)}' 타입은 인덱싱 불가`,
          expr.line, expr.col
        ));
        return T.unknown();
      }

      case 'field_access': {
        const objType = this.checkExpr(expr.object, env);
        return this.inferFieldType(objType, expr.field, expr.line, expr.col);
      }

      case 'assign': {
        const valType = this.checkExpr(expr.value, env);
        const targetType = this.checkExpr(expr.target, env);
        this.sub.unify(targetType, valType);
        return valType;
      }

      case 'array_lit': {
        if (expr.elements.length === 0) return T.array(freshVar());
        const first = this.checkExpr(expr.elements[0], env);
        for (let i = 1; i < expr.elements.length; i++) {
          const et = this.checkExpr(expr.elements[i], env);
          this.sub.unify(first, et);
        }
        return T.array(this.sub.apply(first));
      }

      case 'tensor_lit': {
        // shape는 파서가 계산해둠
        return T.tensor(expr.shape.map(s => s as number));
      }

      case 'matmul': {
        const lt = this.checkExpr(expr.left, env);
        const rt = this.checkExpr(expr.right, env);
        // 결과 shape 추론: [N,M] @ [M,K] → [N,K]
        if (lt.tag === 'tensor' && rt.tag === 'tensor') {
          const N = lt.shape[0];
          const K = rt.shape[1] ?? '?';
          return T.tensor([N, K]);
        }
        return T.tensor(['?', '?']);
      }

      case 'transpose': {
        const t = this.checkExpr(expr.operand, env);
        if (t.tag === 'tensor' && t.shape.length === 2) {
          return T.tensor([t.shape[1], t.shape[0]], t.dtype);
        }
        return T.tensor(['?', '?']);
      }

      case 'if_expr': {
        this.checkExpr(expr.condition, env);
        const thenEnv = env.child();
        for (const s of expr.then) this.checkStmt(s, thenEnv);
        const elseEnv = env.child();
        for (const s of expr.else_) this.checkStmt(s, elseEnv);
        return T.unknown();
      }

      case 'fn_lit': {
        const paramTypes = expr.params.map(p => p.type ? annotToType(p.type) : freshVar());
        const retType = expr.returnType ? annotToType(expr.returnType) : freshVar();
        const inner = env.child();
        expr.params.forEach((p, i) => inner.define(p.name, paramTypes[i]));
        const prevRet = this.returnType;
        this.returnType = retType;
        if (expr.body.kind === 'block_expr') {
          for (const s of expr.body.stmts) this.checkStmt(s, inner);
        }
        this.returnType = prevRet;
        return T.fn(paramTypes, retType);
      }

      case 'block_expr': {
        const inner = env.child();
        for (const s of expr.stmts) this.checkStmt(s, inner);
        if (expr.expr) return this.checkExpr(expr.expr, inner);
        return T.void_();
      }

      case 'grad_block': {
        const inner = env.child();
        for (const s of expr.body) this.checkStmt(s, inner);
        return T.void_();
      }

      case 'struct_lit': {
        return { tag: 'struct', name: expr.structName, fields: {} };
      }

      case 'match_expr': {
        this.checkExpr(expr.subject, env);
        return T.unknown();
      }

      case 'try': {
        return this.checkExpr(expr.operand, env);
      }

      default:
        return T.unknown();
    }
  }

  // ─── 필드 타입 추론 ─────────────────────────────────────────

  private inferFieldType(objType: FL8Type, field: string, line: number, col: number): FL8Type {
    if (objType.tag === 'unknown') return T.unknown();

    if (objType.tag === 'struct') {
      const ft = objType.fields[field];
      if (ft) return ft;
      this.errors.push(noField(objType.name, field, line, col));
      return T.unknown();
    }

    // ML 타입 필드
    const mlKey = this.mlTypeKey(objType);
    if (mlKey) {
      const fields = ML_FIELD_TYPES[mlKey];
      if (fields) {
        const ft = fields[field];
        if (ft) return ft;
      }
      // 알 수 없는 필드는 unknown으로 허용 (동적 메서드 지원)
      return T.unknown();
    }

    // 배열 메서드
    if (objType.tag === 'array') {
      switch (field) {
        case 'length': return T.num();
        case 'push':   return T.fn([objType.elem], T.void_());
        case 'pop':    return T.fn([], objType.elem);
        case 'map':    return T.fn([T.fn([objType.elem], T.unknown())], T.array(T.unknown()));
        case 'filter': return T.fn([T.fn([objType.elem], T.bool())], T.array(objType.elem));
        case 'join':   return T.fn([T.str()], T.str());
        case 'slice':  return T.fn([T.num(), T.num()], T.array(objType.elem));
        default: return T.unknown();
      }
    }

    // 문자열 메서드
    if (objType.tag === 'string') {
      switch (field) {
        case 'length':     return T.num();
        case 'split':      return T.fn([T.str()], T.array(T.str()));
        case 'trim':       return T.fn([], T.str());
        case 'toUpperCase': return T.fn([], T.str());
        case 'toLowerCase': return T.fn([], T.str());
        case 'includes':   return T.fn([T.str()], T.bool());
        default:           return T.unknown();
      }
    }

    return T.unknown();
  }

  private mlTypeKey(t: FL8Type): string | null {
    switch (t.tag) {
      case 'mlp':     return 'mlp';
      case 'adam':
      case 'adamw':   return t.tag;
      case 'gpt':     return 'gpt';
      case 'tokenizer': return t.kind === 'char' ? 'char_tokenizer' : 'bpe_tokenizer';
      default:        return null;
    }
  }

  // ─── 유틸 ────────────────────────────────────────────────────

  hasErrors(): boolean { return this.errors.length > 0; }

  formatErrors(): string {
    return this.errors.map(e => e.toString()).join('\n');
  }
}

// ============================================================
// 공개 API
// ============================================================

export function typeCheck(program: Program): {
  env: TypeEnv;
  errors: TypeErrorReport[];
  ok: boolean;
} {
  const checker = new TypeChecker();
  const env = checker.check(program);
  return { env, errors: checker.errors, ok: !checker.hasErrors() };
}

