// FreeLang v8 ML — Phase 8 타입 시스템 테스트
import { Lexer } from '../src/lexer/lexer';
import { Parser } from '../src/parser/parser';
import { typeCheck } from '../src/types/type_checker';
import { TypeEnv, T, typeToString, typeEqual, makeBuiltinEnv, FL8Type } from '../src/types/type_env';
import { typeMismatch, undefinedVar, wrongArity, noField } from '../src/types/type_error';
import { Interpreter } from '../src/runtime/interpreter';

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
  }
}

function assert(cond: boolean, msg: string) {
  if (!cond) throw new Error(msg);
}

// FL8 소스 → 타입 체크 결과
function check(src: string) {
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors: parseErrors } = new Parser(tokens).parse();
  if (parseErrors.length > 0) throw new Error(`파서: ${parseErrors[0].message}`);
  return typeCheck(program);
}

// FL8 소스 → 오류 없음 검증
function expectOk(src: string): ReturnType<typeof typeCheck> {
  const result = check(src);
  if (result.errors.length > 0) {
    throw new Error(`예상치 못한 타입 오류:\n  ${result.errors.map(e => e.message).join('\n  ')}`);
  }
  return result;
}

// FL8 소스 → 특정 오류 포함 검증
function expectError(src: string, kind: string): ReturnType<typeof typeCheck> {
  const result = check(src);
  const found = result.errors.some(e => e.kind === kind);
  if (!found) {
    const got = result.errors.map(e => e.kind).join(', ') || '없음';
    throw new Error(`'${kind}' 오류 기대, 실제: [${got}]`);
  }
  return result;
}

function run(src: string) {
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  if (errors.length > 0) throw new Error(`파서: ${errors[0].message}`);
  new Interpreter().run(program);
}

// ======================================================
// 1. FL8Type & TypeEnv
// ======================================================
console.log('\n[1] FL8Type & TypeEnv');

test('T 생성자: number', () => {
  const t = T.num();
  assert(t.tag === 'number', `tag: ${t.tag}`);
});

test('T 생성자: array', () => {
  const t = T.array(T.num());
  assert(t.tag === 'array', `tag: ${t.tag}`);
  assert((t as any).elem.tag === 'number', `elem: ${(t as any).elem.tag}`);
});

test('T 생성자: tensor', () => {
  const t = T.tensor([2, 3]);
  assert(t.tag === 'tensor', `tag: ${t.tag}`);
  assert((t as any).shape[0] === 2, `shape: ${(t as any).shape}`);
});

test('T 생성자: fn', () => {
  const t = T.fn([T.num(), T.str()], T.bool());
  assert(t.tag === 'fn', `tag: ${t.tag}`);
  assert((t as any).params.length === 2, `params: ${(t as any).params.length}`);
});

test('typeToString: number', () => {
  assert(typeToString(T.num()) === 'number', typeToString(T.num()));
});

test('typeToString: array<number>', () => {
  assert(typeToString(T.array(T.num())) === 'Array<number>', typeToString(T.array(T.num())));
});

test('typeToString: tensor', () => {
  const s = typeToString(T.tensor([2, 3]));
  assert(s.includes('Tensor'), `tensor: ${s}`);
  assert(s.includes('2') && s.includes('3'), `shape: ${s}`);
});

test('typeToString: fn', () => {
  const s = typeToString(T.fn([T.num()], T.str()));
  assert(s.includes('->'), `fn: ${s}`);
  assert(s.includes('number'), `param: ${s}`);
  assert(s.includes('string'), `ret: ${s}`);
});

test('typeEqual: 동일 태그', () => {
  assert(typeEqual(T.num(), T.num()), 'num == num');
  assert(typeEqual(T.bool(), T.bool()), 'bool == bool');
  assert(!typeEqual(T.num(), T.str()), 'num != str');
});

test('typeEqual: array 원소 비교', () => {
  assert(typeEqual(T.array(T.num()), T.array(T.num())), 'array<num>');
  assert(!typeEqual(T.array(T.num()), T.array(T.str())), 'array<num> != array<str>');
});

test('typeEqual: tensor wildcard ?', () => {
  const a = T.tensor([2, '?']);
  const b = T.tensor([2, 3]);
  assert(typeEqual(a, b), 'tensor wildcard 허용');
});

test('TypeEnv: define & lookup', () => {
  const env = new TypeEnv();
  env.define('x', T.num());
  const t = env.lookup('x');
  assert(t?.tag === 'number', `lookup: ${t?.tag}`);
});

test('TypeEnv: child scope 상속', () => {
  const parent = new TypeEnv();
  parent.define('x', T.num());
  const child = parent.child();
  assert(child.lookup('x')?.tag === 'number', '상속 실패');
});

test('TypeEnv: child scope 차단 없음', () => {
  const parent = new TypeEnv();
  parent.define('x', T.num());
  const child = parent.child();
  child.define('x', T.str());  // 자식에서 재정의
  assert(child.lookup('x')?.tag === 'string', '자식 shadow 실패');
  assert(parent.lookup('x')?.tag === 'number', '부모 영향 없어야 함');
});

test('makeBuiltinEnv: print 정의됨', () => {
  const env = makeBuiltinEnv();
  const t = env.lookup('print');
  assert(t?.tag === 'fn', `print: ${t?.tag}`);
});

test('makeBuiltinEnv: zeros, ones, randn', () => {
  const env = makeBuiltinEnv();
  assert(env.lookup('zeros')?.tag === 'fn', 'zeros');
  assert(env.lookup('ones')?.tag === 'fn', 'ones');
  assert(env.lookup('randn')?.tag === 'fn', 'randn');
});

test('makeBuiltinEnv: MiniGPT, CharTokenizer', () => {
  const env = makeBuiltinEnv();
  assert(env.lookup('MiniGPT')?.tag === 'fn', 'MiniGPT');
  assert(env.lookup('CharTokenizer')?.tag === 'fn', 'CharTokenizer');
});

