console.log('\n[2] 타입 오류 생성자');

test('typeMismatch: 메시지 포함', () => {
  const e = typeMismatch('number', 'string', 1, 1);
  assert(e.kind === 'type_mismatch', `kind: ${e.kind}`);
  assert(e.message.includes('number'), `msg: ${e.message}`);
  assert(e.message.includes('string'), `msg: ${e.message}`);
});

test('undefinedVar: 변수명 포함', () => {
  const e = undefinedVar('foo', 3, 5);
  assert(e.kind === 'undefined_variable', `kind: ${e.kind}`);
  assert(e.message.includes('foo'), `msg: ${e.message}`);
  assert(e.line === 3 && e.col === 5, `loc: ${e.line}:${e.col}`);
});

test('wrongArity: 수 포함', () => {
  const e = wrongArity('add', 2, 3, 1, 1);
  assert(e.kind === 'wrong_arity', `kind: ${e.kind}`);
  assert(e.message.includes('2'), `msg: ${e.message}`);
  assert(e.message.includes('3'), `msg: ${e.message}`);
