// FreeLang v8 ML — 파일 I/O 표준 라이브러리 (Phase 9)

import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';

// ============================================================
// 결과 타입
// ============================================================

export type FsResult<T> =
  | { ok: true; value: T }
  | { ok: false; error: string };

function ok<T>(value: T): FsResult<T> { return { ok: true, value }; }
function err<T>(e: unknown): FsResult<T> {
  return { ok: false, error: e instanceof Error ? e.message : String(e) };
}

// ============================================================
// 파일 읽기/쓰기
// ============================================================

export function readFile(filePath: string, encoding: BufferEncoding = 'utf-8'): FsResult<string> {
  try {
    return ok(fs.readFileSync(filePath, encoding));
  } catch (e) { return err(e); }
}

export function writeFile(filePath: string, content: string): FsResult<void> {
  try {
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, content, 'utf-8');
    return ok(undefined);
  } catch (e) { return err(e); }
}

export function appendFile(filePath: string, content: string): FsResult<void> {
  try {
    fs.appendFileSync(filePath, content, 'utf-8');
    return ok(undefined);
  } catch (e) { return err(e); }
}

export function deleteFile(filePath: string): FsResult<void> {
  try {
    fs.unlinkSync(filePath);
    return ok(undefined);
  } catch (e) { return err(e); }
}

// ============================================================
// 파일 정보
// ============================================================

export function fileExists(filePath: string): boolean {
  return fs.existsSync(filePath);
}

export interface FileStat {
  size: number;
  isFile: boolean;
  isDir: boolean;
  modified: number;  // Unix timestamp ms
  created: number;
}

export function statFile(filePath: string): FsResult<FileStat> {
  try {
    const s = fs.statSync(filePath);
    return ok({
      size: s.size,
      isFile: s.isFile(),
      isDir: s.isDirectory(),
      modified: s.mtimeMs,
      created: s.birthtimeMs,
    });
  } catch (e) { return err(e); }
}

// ============================================================
// 디렉토리
// ============================================================

export function listDir(dirPath: string): FsResult<string[]> {
  try {
    return ok(fs.readdirSync(dirPath));
  } catch (e) { return err(e); }
}

export function makeDir(dirPath: string): FsResult<void> {
  try {
    fs.mkdirSync(dirPath, { recursive: true });
    return ok(undefined);
  } catch (e) { return err(e); }
}

export function removeDir(dirPath: string): FsResult<void> {
  try {
    fs.rmSync(dirPath, { recursive: true, force: true });
    return ok(undefined);
  } catch (e) { return err(e); }
}

// ============================================================
// JSON 파일
// ============================================================

export function readJson(filePath: string): FsResult<unknown> {
  const r = readFile(filePath);
  if (!r.ok) return r;
  try {
    return ok(JSON.parse(r.value));
  } catch (e) { return err(e); }
}

export function writeJson(filePath: string, data: unknown, pretty = true): FsResult<void> {
  return writeFile(filePath, JSON.stringify(data, null, pretty ? 2 : 0));
}

// ============================================================
// CSV 파일
// ============================================================

export function readCsv(filePath: string, delimiter = ','): FsResult<string[][]> {
  const r = readFile(filePath);
  if (!r.ok) return r as FsResult<string[][]>;
  const rows = r.value
    .split('\n')
    .filter(l => l.trim().length > 0)
    .map(l => l.split(delimiter).map(c => c.trim()));
  return ok(rows);
}

export function writeCsv(filePath: string, rows: string[][], delimiter = ','): FsResult<void> {
  const content = rows.map(r => r.join(delimiter)).join('\n');
  return writeFile(filePath, content);
}

// ============================================================
// 경로 유틸
// ============================================================

export const pathUtils = {
  join: (...parts: string[]) => path.join(...parts),
  dirname: (p: string) => path.dirname(p),
  basename: (p: string, ext?: string) => path.basename(p, ext),
  extname: (p: string) => path.extname(p),
  resolve: (...parts: string[]) => path.resolve(...parts),
  relative: (from: string, to: string) => path.relative(from, to),
  isAbsolute: (p: string) => path.isAbsolute(p),
  tmpDir: () => os.tmpdir(),
  homeDir: () => os.homedir(),
  cwd: () => process.cwd(),
};

// ============================================================
// .fl8 런타임 래퍼 (인터프리터에서 호출)
// ============================================================

export const FL8_FS = {
  read:        (p: string) => { const r = readFile(p); return r.ok ? r.value : null; },
  write:       (p: string, c: string) => { const r = writeFile(p, c); return r.ok; },
  append:      (p: string, c: string) => { const r = appendFile(p, c); return r.ok; },
  delete:      (p: string) => { const r = deleteFile(p); return r.ok; },
  exists:      (p: string) => fileExists(p),
  stat:        (p: string) => { const r = statFile(p); return r.ok ? r.value : null; },
  ls:          (p: string) => { const r = listDir(p); return r.ok ? r.value : []; },
  mkdir:       (p: string) => { const r = makeDir(p); return r.ok; },
  readJson:    (p: string) => { const r = readJson(p); return r.ok ? r.value : null; },
  writeJson:   (p: string, d: unknown) => { const r = writeJson(p, d); return r.ok; },
  readCsv:     (p: string) => { const r = readCsv(p); return r.ok ? r.value : []; },
  writeCsv:    (p: string, rows: string[][]) => { const r = writeCsv(p, rows); return r.ok; },
  join:        pathUtils.join,
  dirname:     pathUtils.dirname,
  basename:    pathUtils.basename,
  extname:     pathUtils.extname,
  tmpDir:      pathUtils.tmpDir,
  homeDir:     pathUtils.homeDir,
  cwd:         pathUtils.cwd,
};

