// FreeLang v8 ML — HTTP 클라이언트 표준 라이브러리 (Phase 9)

import { spawnSync } from 'child_process';
import * as https from 'https';
import * as http from 'http';
import { URL } from 'url';

// ============================================================
// 타입
// ============================================================

export interface HttpResponse {
  status: number;
  statusText: string;
  headers: Record<string, string>;
  body: string;
  ok: boolean;
}

export interface HttpOptions {
  method?: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
  headers?: Record<string, string>;
  body?: string | object;
  timeout?: number;  // ms
}

// ============================================================
// HTTP 요청 (Node.js 내장 http/https)
// ============================================================

export function request(url: string, options: HttpOptions = {}): Promise<HttpResponse> {
  return new Promise((resolve, reject) => {
    const parsed = new URL(url);
    const isHttps = parsed.protocol === 'https:';

    const bodyStr = options.body
      ? typeof options.body === 'string'
        ? options.body
        : JSON.stringify(options.body)
      : '';

    const reqOptions: http.RequestOptions = {
      hostname: parsed.hostname,
      port: parsed.port || (isHttps ? 443 : 80),
      path: parsed.pathname + parsed.search,
      method: options.method ?? 'GET',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(bodyStr),
        'User-Agent': 'FreeLang/8.0 fl8-http',
        ...options.headers,
      },
    };

    const lib = isHttps ? https : http;
    const req = lib.request(reqOptions, (res) => {
      let body = '';
      res.on('data', chunk => { body += chunk; });
      res.on('end', () => {
        resolve({
          status: res.statusCode ?? 0,
          statusText: res.statusMessage ?? '',
          headers: res.headers as Record<string, string>,
          body,
          ok: (res.statusCode ?? 0) >= 200 && (res.statusCode ?? 0) < 300,
        });
      });
    });

    req.on('error', reject);

    if (options.timeout) {
      req.setTimeout(options.timeout, () => {
        req.destroy();
        reject(new Error(`타임아웃: ${options.timeout}ms`));
      });
    }

    if (bodyStr) req.write(bodyStr);
    req.end();
  });
}

// ============================================================
// 편의 함수 (동기 래퍼 — spawnSync 사용)
// ============================================================

export function requestSync(url: string, options: HttpOptions = {}): HttpResponse {
  const method = options.method ?? 'GET';
  const bodyStr = options.body
    ? typeof options.body === 'string'
      ? options.body
      : JSON.stringify(options.body)
    : '';

  const args = ['-s', '-w', '\n__STATUS__%{http_code}', '-X', method];

  if (options.headers) {
    for (const [k, v] of Object.entries(options.headers)) {
      args.push('-H', `${k}: ${v}`);
    }
  }

  if (bodyStr) {
    args.push('-d', bodyStr);
    if (!options.headers?.['Content-Type']) {
      args.push('-H', 'Content-Type: application/json');
    }
  }

  if (options.timeout) {
    args.push('--max-time', String(options.timeout / 1000));
  }

  args.push(url);

  const result = spawnSync('curl', args, { encoding: 'utf-8', timeout: (options.timeout ?? 30000) + 1000 });

  if (result.error) {
    return { status: 0, statusText: result.error.message, headers: {}, body: '', ok: false };
  }

  const output = result.stdout ?? '';
  const statusMatch = output.match(/__STATUS__(\d+)$/);
  const status = statusMatch ? parseInt(statusMatch[1]) : 0;
  const body = output.replace(/__STATUS__\d+$/, '').trimEnd();

  return {
    status,
    statusText: status >= 200 && status < 300 ? 'OK' : 'Error',
    headers: {},
    body,
    ok: status >= 200 && status < 300,
  };
}

export function get(url: string, headers?: Record<string, string>): HttpResponse {
  return requestSync(url, { method: 'GET', headers });
}

export function post(url: string, body: object | string, headers?: Record<string, string>): HttpResponse {
  return requestSync(url, { method: 'POST', body, headers });
}

export function put(url: string, body: object | string): HttpResponse {
  return requestSync(url, { method: 'PUT', body });
}

export function del(url: string): HttpResponse {
  return requestSync(url, { method: 'DELETE' });
}

// ============================================================
// JSON API 헬퍼
// ============================================================

export function getJson(url: string): unknown | null {
  const r = get(url, { Accept: 'application/json' });
  if (!r.ok) return null;
  try { return JSON.parse(r.body); } catch { return null; }
}

export function postJson(url: string, data: object): unknown | null {
  const r = post(url, data, { 'Accept': 'application/json' });
  if (!r.ok) return null;
  try { return JSON.parse(r.body); } catch { return r.body; }
}

// ============================================================
// URL 유틸
// ============================================================

export const urlUtils = {
  parse: (url: string) => {
    try {
      const u = new URL(url);
      return {
        protocol: u.protocol,
        host: u.host,
        hostname: u.hostname,
        port: u.port,
        pathname: u.pathname,
        search: u.search,
        hash: u.hash,
      };
    } catch { return null; }
  },
  encode: encodeURIComponent,
  decode: decodeURIComponent,
  buildQuery: (params: Record<string, string>) =>
    new URLSearchParams(params).toString(),
};

// ============================================================
// .fl8 런타임 래퍼
// ============================================================

export const FL8_HTTP = {
