    return this.select(table, where).rows.length;
  }

  // ─── SQL 파싱 (기본 서브셋) ─────────────────────────────────

  query(sql: string): QueryResult {
    const s = sql.trim().toUpperCase();

    if (s.startsWith('SELECT')) return this.parsedSelect(sql);
    if (s.startsWith('INSERT')) return this.parsedInsert(sql);
    if (s.startsWith('UPDATE')) return this.parsedUpdate(sql);
    if (s.startsWith('DELETE')) return this.parsedDelete(sql);
    if (s.startsWith('CREATE TABLE')) return this.parsedCreate(sql);
    if (s.startsWith('DROP TABLE')) return this.parsedDrop(sql);

    return { rows: [], rowsAffected: 0, lastInsertId: 0 };
  }

  private parsedCreate(sql: string): QueryResult {
    // CREATE TABLE name (col1, col2, ...)
    const m = sql.match(/CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?(\w+)\s*\(([^)]+)\)/i);
    if (!m) return { rows: [], rowsAffected: 0, lastInsertId: 0 };
    const name = m[1];
    const cols = m[2].split(',').map(c => c.trim().split(/\s+/)[0]);
    return this.createTable(name, cols);
  }

  private parsedDrop(sql: string): QueryResult {
    const m = sql.match(/DROP\s+TABLE\s+(?:IF\s+EXISTS\s+)?(\w+)/i);
    if (!m) return { rows: [], rowsAffected: 0, lastInsertId: 0 };
    return this.dropTable(m[1]);
  }

  private parsedSelect(sql: string): QueryResult {
    // SELECT col1,col2 FROM table WHERE col=val
    const fromM = sql.match(/FROM\s+(\w+)/i);
    if (!fromM) return { rows: [], rowsAffected: 0, lastInsertId: 0 };
    const table = fromM[1];

    const colM = sql.match(/SELECT\s+(.*?)\s+FROM/i);
    const cols = colM ? (colM[1].trim() === '*' ? undefined : colM[1].split(',').map(c => c.trim())) : undefined;

    const where = this.parseWhere(sql);
    return this.select(table, where, cols);
  }

  private parsedInsert(sql: string): QueryResult {
    // INSERT INTO table (col1, col2) VALUES (val1, val2)
    const m = sql.match(/INSERT\s+INTO\s+(\w+)\s*\(([^)]+)\)\s*VALUES\s*\(([^)]+)\)/i);
    if (!m) return { rows: [], rowsAffected: 0, lastInsertId: 0 };
    const table = m[1];
    const cols = m[2].split(',').map(c => c.trim());
    const vals = m[3].split(',').map(v => this.parseValue(v.trim()));
    const row: Row = {};
    cols.forEach((c, i) => row[c] = vals[i]);
    return this.insert(table, row);
  }

  private parsedUpdate(sql: string): QueryResult {
    // UPDATE table SET col1=val1, col2=val2 WHERE col=val
    const tableM = sql.match(/UPDATE\s+(\w+)\s+SET/i);
    if (!tableM) return { rows: [], rowsAffected: 0, lastInsertId: 0 };
    const table = tableM[1];

    const setM = sql.match(/SET\s+(.*?)(?:\s+WHERE|$)/i);
    if (!setM) return { rows: [], rowsAffected: 0, lastInsertId: 0 };
    const set: Row = {};
    for (const pair of setM[1].split(',')) {
      const [k, v] = pair.split('=');
      if (k && v) set[k.trim()] = this.parseValue(v.trim());
    }

    return this.update(table, set, this.parseWhere(sql));
  }

  private parsedDelete(sql: string): QueryResult {
    // DELETE FROM table WHERE col=val
    const m = sql.match(/DELETE\s+FROM\s+(\w+)/i);
    if (!m) return { rows: [], rowsAffected: 0, lastInsertId: 0 };
    return this.delete(m[1], this.parseWhere(sql));
  }

  private parseWhere(sql: string): Partial<Row> | undefined {
    const whereM = sql.match(/WHERE\s+(.+?)(?:\s+ORDER|\s+LIMIT|$)/i);
    if (!whereM) return undefined;
    const where: Partial<Row> = {};
    for (const cond of whereM[1].split(/\s+AND\s+/i)) {
      const [k, v] = cond.split('=');
      if (k && v) where[k.trim()] = this.parseValue(v.trim());
    }
    return where;
  }

  private parseValue(v: string): SqlValue {
    if (v === 'NULL' || v === 'null') return null;
    if (v === 'true') return true;
    if (v === 'false') return false;
    if ((v.startsWith("'") && v.endsWith("'")) ||
        (v.startsWith('"') && v.endsWith('"'))) {
      return v.slice(1, -1);
    }
    const n = Number(v);
    return isNaN(n) ? v : n;
  }

  // ─── 트랜잭션 ────────────────────────────────────────────────

  transaction(fn: (db: FL8Db) => void): boolean {
    const snapshot = JSON.stringify(this.data);
    try {
      fn(this);
      return true;
    } catch {
      this.data = JSON.parse(snapshot);
      this.dirty = false;
      return false;
    }
  }

  // ─── 영속화 ──────────────────────────────────────────────────

  save(filePath?: string): boolean {
    const target = filePath ?? this.filePath;
    if (!target) return false;
    try {
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, JSON.stringify(this.data, null, 2));
      this.dirty = false;
      return true;
    } catch { return false; }
  }

  // ─── 내부 헬퍼 ───────────────────────────────────────────────

  private getTable(name: string): TableData {
    if (!this.data.tables[name]) {
      throw new Error(`테이블 없음: '${name}'`);
    }
    return this.data.tables[name];
  }
}

// ============================================================
// .fl8 런타임 래퍼
// ============================================================

const _openDbs = new Map<string, FL8Db>();

export const FL8_SQLITE = {
  open: (path: string) => {
    if (!_openDbs.has(path)) _openDbs.set(path, new FL8Db(path));
    return path;  // 핸들로 경로 사용
  },
  close: (handle: string) => { _openDbs.delete(handle); },
  query: (handle: string, sql: string) => {
    const db = _openDbs.get(handle);
    if (!db) return { rows: [], rowsAffected: 0, lastInsertId: 0 };
    return db.query(sql);
  },
  insert: (handle: string, table: string, row: Row) => {
    const db = _openDbs.get(handle);
    if (!db) return 0;
    return db.insert(table, row).lastInsertId;
  },
  select: (handle: string, table: string, where?: Row) => {
    const db = _openDbs.get(handle);
    if (!db) return [];
    return db.select(table, where).rows;
  },
  update: (handle: string, table: string, set: Row, where?: Row) => {
    const db = _openDbs.get(handle);
    if (!db) return 0;
    return db.update(table, set, where).rowsAffected;
  },
  delete: (handle: string, table: string, where?: Row) => {
    const db = _openDbs.get(handle);
    if (!db) return 0;
    return db.delete(table, where).rowsAffected;
  },
  createTable: (handle: string, name: string, cols: string[]) => {
    const db = _openDbs.get(handle);
    if (!db) return false;
    db.createTable(name, cols);
    return true;
  },
  count: (handle: string, table: string, where?: Row) => {
    const db = _openDbs.get(handle);
    if (!db) return 0;
    return db.count(table, where);
  },
  save: (handle: string) => {
    const db = _openDbs.get(handle);
    return db?.save() ?? false;
  },
  inMemory: () => {
    const id = `__mem_${Date.now()}`;
    _openDbs.set(id, new FL8Db());
    return id;
  },
};
